insert into private.study_guides (guide, chunks, sha256) values ('study_guide_bua205', 35, 'd06a157012ef44355c43e6b0c5516d8092736e3fc7c670b10819ff911f5a90b9');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 1, $study_guide${"guide":"study_guide_bua205","code":"BUA205","courseId":"40000000-0000-4000-8000-000000000004","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"22b198d9-ebcc-5801-8874-d9dd325124e5","before":{"title":"Leadership and Governance","body":"Leadership theories and styles, organisational ethics, governance frameworks, and stakeholder management across the public and private sectors.","examFocus":["Leadership theory definitions and applications","Leadership styles and situational leadership","Ethical leadership principles","Governance structures and responsibilities","Stakeholder analysis and management","Essays on organizational leadership"]},"after":{"title":"Leadership and Governance","body":"Leadership theories and styles, organisational ethics, governance frameworks, and stakeholder management across the public and private sectors.","examFocus":["Leadership theory definitions and applications","Leadership styles and situational leadership","Ethical leadership principles","Governance structures and responsibilities","Stakeholder analysis and management","Essays on organizational leadership"],"outcomes":["Discuss the meaning of leadership and governance.","Identify the basic concepts and elements of governance.","Explain governance in the public sector and its challenges.","Identify gaps in public governance and initiatives to improve them.","Identify traditional and contemporary leadership theories and styles.","Apply moral philosophies to leadership and governance problems.","Explain how citizens and civil society can be engaged in governance reform.","Take an active part in public sector reform in Nigeria."],"assessment":["Expect objective questions, with possible short theory questions. Expect definitions, lists, theories and who proposed them, and Nigerian applications.","Every topic is examinable."]}},"retire":[{"itemId":"28932a9f-ba8f-5c57-bec6-a5b8d3bc224b","revision":1,"parentRevision":null},{"itemId":"ed217ffe-abdb-57e8-a2c3-715c6547645f","revision":1,"parentRevision":null},{"itemId":"f437e169-fc52-5db4-a548-0274ad0832e7","revision":1,"parentRevision":null},{"itemId":"87cf5ce4-3ab8-570e-b67b-9d053c0fe548","revision":1,"parentRevision":null},{"itemId":"5f80133e-26fa-5189-b1e0-d28929398208","revision":1,"parentRevision":null},{"itemId":"f37b54e4-b347-5295-8462-9d0e1050c122","revision":1,"parentRevision":null},{"itemId":"1a63a6b5-b8c3-596b-bcaf-7860609473c0","revision":1,"parentRevision":null},{"itemId":"d622aa2c-eb68-5c6d-bacf-06a5f165802c","revision":1,"parentRevision":null},{"itemId":"8e32d455-6d75-5309-9015-4020670855cf","revision":1,"parentRevision":null},{"itemId":"8a6a9c00-817e-518f-b267-b58330458216","revision":1,"parentRevision":null}],"notes":[{"kind":"note","itemId":"97fb04af-5684-513a-a5d5-38eda1826c02","sourceKey":"guide-topic:1","position":1,"payload":{"title":"An Overview of Leadership","body":"What leadership means and how it differs from management; power, authority and the five bases of power; the trait, behavioural, contingency and contemporary theories and who proposed each; the qualities and characteristics of effective leaders; the core components, functions and roles of leadership; leadership challenges in governance.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What leadership means and how it differs from management; power, authority and the five bases of power; the trait, behavioural, contingency and contemporary theories and who proposed each; the qualities and characteristics of effective leaders; the core components, functions and roles of leadership; leadership challenges in governance."}],"lessons":[{"number":"1.1","title":"Meaning of leadership, and leadership versus management","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership:","bold":true},{"text":" the "},{"text":"process of influencing others to achieve shared (common) goals","bold":true},{"text":" for collective development. The best one-line answer: \"the process of influencing others to achieve a common goal.\""}]},{"text":[{"text":"Leadership (as an art):","bold":true},{"text":" the art of influencing others to direct their abilities and efforts towards the group's goals. In business: management's ability to induce subordinates to work towards group goals with confidence."}]},{"text":[{"text":"The "},{"text":"core element","bold":true},{"text":" in almost every definition is the ability to "},{"text":"influence behaviour","bold":true},{"text":". "},{"text":"Influence","bold":true},{"text":" = the leader's capacity to "},{"text":"shape attitudes, beliefs and behaviours","bold":true},{"text":"."}]},{"text":[{"text":"Relational process:","bold":true},{"text":" leadership "},{"text":"emerges through interaction between leaders and followers in a specific context","bold":true},{"text":"; it is not a one-person activity. It is "},{"text":"dynamic","bold":true},{"text":" because of this ongoing leader-follower interaction."}]},{"text":[{"text":"Effective leadership depends on "},{"text":"4 things:","bold":true},{"text":" "},{"text":"trust, communication, legitimacy, shared commitment to common objectives","bold":true},{"text":"."}]},{"text":[{"text":"Leadership is a "},{"text":"social influence process","bold":true},{"text":", not confined to formal positions. Modern thought assumes leadership can be "},{"text":"learned and developed over time","bold":true},{"text":"."}]},{"text":[{"text":"Leadership matters in governance because leaders "},{"text":"shape institutional direction, set ethical standards, coordinate collective action and manage competing interests","bold":true},{"text":". The quality of leadership determines "},{"text":"policy direction, institutional performance and citizens' trust","bold":true},{"text":" in institutions."}]}]},{"type":"table","header":[[{"text":"Leadership"}],[{"text":"Management"}]],"rows":[[[{"text":"Copes with "},{"text":"change","bold":true}],[{"text":"Copes with "},{"text":"complexity","bold":true}]]$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 2, $study_guide$,[[{"text":"Long-term "},{"text":"vision and direction","bold":true}],[{"text":"Detailed operational control, planning and budgeting"}]],[[{"text":"Aligns and inspires people"}],[{"text":"Organises, staffs, controls"}]],[[{"text":"\"Doing the right thing\""}],[{"text":"\"Doing things right\""}]],[[{"text":"Rests on influence, trust, legitimacy"}],[{"text":"Rests on formal position and rules"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The defining feature that separates leadership from management is leadership's emphasis on "},{"text":"long-term vision and direction","bold":true},{"text":" (John Kotter: management copes with complexity, leadership copes with change; Warren Bennis: managers do things right, leaders do the right thing). A good executive needs both."}]},{"text":[{"text":"Ralph "},{"text":"Stogdill","bold":true},{"text":" (1974) observed that there are almost as many definitions of leadership as there are people who have tried to define it. Do not worry about one exact wording: any option that says \"influencing others towards a shared or common goal\" is the right one. Options about commanding obedience, managing resources for profit or delegating efficiently are traps."}]},{"text":[{"text":"Leadership as an idea grew in the 20th century as an offshoot of scientific management."}]},{"text":[{"text":"Leadership concepts examiners pair with a phrase (learn the pairing):"}]}]},{"type":"table","header":[[{"text":"Concept"}],[{"text":"Correct pairing"}]],"rows":[[[{"text":"Strategic leadership"}],[{"text":"Aligning vision, resources and capabilities"}]],[[{"text":"Leadership development"}],[{"text":"Influence and interpersonal capability; behavioural flexibility and competence"}]],[[{"text":"Coaching"}],[{"text":"Personalised feedback and growth"}]],[[{"text":"Communication that builds alignment"}],[{"text":"Message clarity and relevance; clear and purposeful"}]],[[{"text":"Communication that encourages dialogue"}],[{"text":"Interactive"}]],[[{"text":"Virtual teams"}],[{"text":"Clear communication and trust"}]],[[{"text":"Leader's role in change"}],[{"text":"Communicate purpose and direction"}]],[[{"text":"Resilience"}],[{"text":"Persisting and adapting under pressure; strengthened by learning from adversity"}]],[[{"text":"Decision-making"}],[{"text":"Balances analysis and judgement"}]],[[{"text":"Judgement"}],[{"text":"Integrating experience with situational insight"}]],[[{"text":"Legitimacy"}],[{"text":"Strengthened by fairness and competence; decisions seen as fair and well-reasoned"}]],[[{"text":"Influence beyond formal authority; sustainable authority"}],[{"text":"Legitimacy and trust"}]],[[{"text":"Clarity"}],[{"text":"Reduces ambiguity and confusion; goals specific and shared"}]],[[{"text":"Leadership culture"}],[{"text":"Shared norms and values shaped by leaders"}]],[[{"text":"Succession planning; continuity"}],[{"text":"Developing future leadership capacity; succession and talent development"}]],[[{"text":"Leadership assessment"}],[{"text":"Influence processes and outcomes"}]],[[{"text":"Emotional intelligence"}],[{"text":"Interpersonal effectiveness"}]],[[{"text":"Self-regulation"}],[{"text":"Emotional control and discipline"}]],[[{"text":"Presence"}],[{"text":"Confidence and authenticity"}]],[[{"text":"Alignment across departments; teams"}],[{"text":"Coordinated performance; role clarity and coordination"}]],[[{"text":"Effectiveness over time; sustainability"}],[{"text":"Continuous learning and adaptation; learning and renewal"}]],[[{"text":"Effectiveness across levels"}],[{"text":"Contextual awareness"}]],[[{"text":"Self-awareness; reflection"}],[{"text":"Enhance effectiveness; critical self-examination"}]],[[{"text":"Learning"}],[{"text":"Most effective when experiential and reflective; from failure = reflection and improvement"}]],[[{"text":"Consistency"}],[{"text":"Predictability and trust"}]],[[{"text":"Credibility"}],[{"text":"Consistent words and actions; undermined by acting against stated values"}]],[[{"text":"Trustworthiness"}],[{"text":"Honouring commitments"}]],[[{"text":"Stability"}],[{"text":"Values clearly articulated and lived"}]],[[{"text":"Role modelling"}],[{"text":"Observed behaviour and example"}]],[[{"text":"Cross-cultural leadership"}],[{"text":"Sensitivity to the cultural norms and values of the people led"}]],[[{"text":"Inclusiveness"}],[{"text":"Valuing diverse perspectives"}]],[[{"text":"Accountability"}],[{"text":"Accepting responsibility for outcomes"}]],[[{"text":"Follower commitment"}],[{"text":"Strongest with shared meaning and purpose"}]],[[{"text":"Adaptability"}],[{"text":"Adjusting behaviour to context; critical in rapid change and uncertainty"}]],[[{"text":"Motivation"}],[{"text":"Aligning tasks with intrinsic values; rewards appeal to "},{"text":"extrinsic","bold":true},{"text":" motivation"}]]]}]},{"number":"1.2","title":"Power, authority and the bases of power","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A leader needs both "},{"text":"power","bold":true},{"text":" and "},{"text":"authority","bold":true},{"text":"."}]},{"text":[{"text":"Power:","bold":true},{"text":" the ability to influence others. It can come from "},{"text":"personal sources","bold":true},{"text":" such as "},{"text":"intelligence, wealth, even beauty","bold":true},{"text":"."}]},{"text":[{"text":"Authority:","bold":true},{"text":" the "},{"text":"right to command","bold":true},{"text":". It is conferred by "},{"text":"culture, society and the organisation","bold":true},{"text":"; in a company it is conferred through the "},{"text":"board of directors","bold":true},{"text":"."}]},{"text":[{"text":"Qualities of authority (4):","bold":true},{"text":" it must be (1) "},{"text":"clear","bold":true},{"text":", (2) "},{"text":"feasible","bold":true},{"text":", (3) "},{"text":"consistent with individual belief and organisational purpose","bold":true},{"text":", (4) "},{"text":"capable of being carried out"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 3, $study_guide$,"bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"French and Raven's 5 bases of power","bold":true},{"text":" (1959):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Legitimate:","bold":true},{"text":" from "},{"text":"organisational position","bold":true},{"text":" (formal right to give orders)."}]},{"text":[{"text":"Reward:","bold":true},{"text":" from control of "},{"text":"incentives","bold":true},{"text":" (pay rise, bonus, promotion). Appeals to extrinsic motivation."}]},{"text":[{"text":"Coercive:","bold":true},{"text":" from the "},{"text":"threat of punishment","bold":true},{"text":" (query, demotion, pay cut, dismissal)."}]},{"text":[{"text":"Expert:","bold":true},{"text":" from "},{"text":"expertise","bold":true},{"text":", special knowledge or skill shown consistently."}]},{"text":[{"text":"Referent:","bold":true},{"text":" from "},{"text":"personal attraction and identification","bold":true},{"text":"; followers admire the leader."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legitimate, reward and coercive power are "},{"text":"positional","bold":true},{"text":" (they come with the office). Expert and referent power are "},{"text":"personal","bold":true},{"text":"; they last beyond the job title. Raven later added "},{"text":"information power","bold":true},{"text":"."}]},{"text":[{"text":"A supervisor who says anyone who misses the quota gets a query and may lose part of a ₦80,000 allowance is using "},{"text":"coercive","bold":true},{"text":" power; offering the ₦80,000 as a bonus for hitting the quota would be "},{"text":"reward","bold":true},{"text":" power."}]},{"text":[{"text":"A trap swaps the definitions: power is "},{"text":"not","bold":true},{"text":" \"the right to command conferred by the board\"; that is "},{"text":"authority","bold":true},{"text":". Authority should never be kept secret from subordinates."}]},{"text":[{"text":"Missing clarity example: a branch manager told to \"handle staff matters as necessary\" with no word on which leave, discipline or hiring decisions she may take lacks "},{"text":"clarity","bold":true},{"text":" of authority."}]}]}]},{"number":"1.3","title":"Trait and behavioural theories","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Great Man Hypothesis:","bold":true},{"text":" leaders are "},{"text":"born, not made","bold":true},{"text":". It is the basis of the "},{"text":"trait approach","bold":true},{"text":"."}]},{"text":[{"text":"Trait theory:","bold":true},{"text":" leaders are "},{"text":"born with inherent personal attributes","bold":true},{"text":" that distinguish them from non-leaders."}]}]},{"type":"paragraph","text":[{"text":"Trait groups (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical:","bold":true},{"text":" height, strength, vigour, appearance."}]},{"text":[{"text":"Intelligence:","bold":true},{"text":" ability to comprehend, conceptualise, plan, think."}]},{"text":[{"text":"Task-related ability:","bold":true},{"text":" initiative, administrative ability."}]},{"text":[{"text":"Personality:","bold":true},{"text":" interpersonal skills, aggressiveness, adaptiveness, quiet, introvert and extrovert."}]}]},{"type":"paragraph","text":[{"text":"Limitations of trait theory:","bold":true},{"text":" (1) "},{"text":"no basis for comparing the traits","bold":true},{"text":"; (2) "},{"text":"ignores situational factors","bold":true},{"text":"; also, researchers never agreed on a consistent list of traits that guarantees effective leadership."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Behavioural theory:","bold":true},{"text":" studies "},{"text":"what leaders actually do","bold":true},{"text":" in practice, not their innate qualities. Limitation: it has "},{"text":"not found one style that works in every situation","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Behavioural type"}],[{"text":"What it looks like"}],[{"text":"Merit"}],[{"text":"Demerit"}]],"rows":[[[{"text":"Autocratic","bold":true}],[{"text":"No participation; subordinates passive; believes in transaction (reward and punishment); leads by coercion; a fault-finder, not a coach; "},{"text":"one-way","bold":true},{"text":" communication"}],[{"text":"Things get done "},{"text":"quickly","bold":true}],[{"text":"Hurts workers' "},{"text":"morale","bold":true}]],[[{"text":"Democratic","bold":true}],[{"text":"Trusts and involves subordinates; a coach; "},{"text":"two-way","bold":true},{"text":" communication; expects feedback"}],[{"text":"Workers motivated and feel recognised"}],[{"text":"Slow","bold":true},{"text":" decision-making"}]],[[{"text":"Laissez-faire","bold":true}],[{"text":"Lets things drift; sets no goals or directives; leader absent; individuals decide alone"}],[{"text":"Boosts "},{"text":"creativity and personal initiative","bold":true},{"text":"; entrepreneurial mindset"}],[{"text":"No direction; group easily "},{"text":"drifts","bold":true}]]]},{"type":"paragraph","text":[{"text":"Classic behavioural studies:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"University of Iowa (Kurt Lewin, 1939):","bold":true},{"text":" autocratic, democratic, laissez-faire."}]},{"text":[{"text":"Ohio State studies (late 1940s):","bold":true},{"text":" "},{"text":"initiating structure","bold":true},{"text":" (organising tasks, roles, deadlines) and "},{"text":"consideration","bold":true},{"text":" (friendship, respect for ideas, concern for welfare)."}]},{"text":[{"text":"University of Michigan (Rensis Likert):","bold":true},{"text":" "},{"text":"employee-centred","bold":true},{"text":" versus "},{"text":"job (production)-centred","bold":true},{"text":"."}]},{"text":[{"text":"Managerial Grid (Blake and Mouton, 1964):","bold":true},{"text":" concern for production (first number) and concern for people (second number), each 1 to 9."}]}]},{"type":"table","header":[$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 4, $study_guide$[{"text":"Grid position"}],[{"text":"Style"}]],"rows":[[[{"text":"1,1"}],[{"text":"Impoverished"}]],[[{"text":"9,1"}],[{"text":"Authority-compliance (task)"}]],[[{"text":"1,9"}],[{"text":"Country club"}]],[[{"text":"5,5"}],[{"text":"Middle-of-the-road"}]],[[{"text":"9,9"}],[{"text":"Team management (the ideal)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stogdill's review of trait studies (1948) found no trait set that made someone a leader in every situation; this pushed research towards behaviour and situations."}]},{"text":[{"text":"Trap: \"social-class traits such as family name and inheritance\" is "},{"text":"not","bold":true},{"text":" a trait group. \"Anyone can become a leader through training\" is "},{"text":"not","bold":true},{"text":" a limitation of trait theory; it is the opposite of what trait theory claims."}]},{"text":[{"text":"Pairing traps: initiative = task-related (not personality); aggressiveness = personality; vigour = physical; ability to plan = intelligence."}]},{"text":[{"text":"Case: a Lagos MD who did well in stable years but failed in a currency crisis with the same qualities shows that trait theory "},{"text":"ignores situational factors","bold":true},{"text":". Two consultants unable to agree how to measure who has more \"vigour\" shows "},{"text":"no basis for comparing traits","bold":true},{"text":"."}]},{"text":[{"text":"A friendly Ikeja supervisor who respects workers' ideas and cares about their welfare scores high on "},{"text":"consideration","bold":true},{"text":". A manager with relaxed rules and parties but missed targets is "},{"text":"country club (1,9)","bold":true},{"text":"."}]},{"text":[{"text":"The Managerial Grid is "},{"text":"behavioural","bold":true},{"text":", not contingency."}]}]}]},{"number":"1.4","title":"Contingency and situational theories","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Contingency view:","bold":true},{"text":" "},{"text":"no single style is universally effective","bold":true},{"text":"; effectiveness depends on the "},{"text":"match between leadership style and situational factors","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Fiedler's contingency model (Fred Fiedler, 1967):","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"Least Preferred Co-worker (LPC) scale","bold":true},{"text":" shows whether a leader is "},{"text":"task-oriented","bold":true},{"text":" (low LPC) or "},{"text":"relationship-oriented","bold":true},{"text":" (high LPC)."}]},{"text":[{"text":"3 situational factors:","bold":true},{"text":" (1) "},{"text":"leader-member relations","bold":true},{"text":", (2) "},{"text":"task structure","bold":true},{"text":", (3) "},{"text":"position power","bold":true},{"text":"."}]},{"text":[{"text":"Task-oriented leaders do best in "},{"text":"very favourable or very unfavourable","bold":true},{"text":" situations; relationship-oriented leaders do best in "},{"text":"moderately favourable","bold":true},{"text":" ones."}]},{"text":[{"text":"Style is "},{"text":"fixed","bold":true},{"text":", so "},{"text":"match the leader to the situation or change the situation","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Hersey and Blanchard's Situational Leadership Theory (1969):","bold":true},{"text":" adapt style to followers' "},{"text":"maturity (readiness)","bold":true},{"text":" and task demands."}]},{"type":"table","header":[[{"text":"Follower readiness"}],[{"text":"Style"}],[{"text":"Task behaviour"}],[{"text":"Relationship behaviour"}]],"rows":[[[{"text":"R1: unable and unwilling or insecure"}],[{"text":"S1 Telling","bold":true},{"text":" (directing)"}],[{"text":"High"}],[{"text":"Low"}]],[[{"text":"R2: unable but willing or confident"}],[{"text":"S2 Selling","bold":true},{"text":" (coaching)"}],[{"text":"High"}],[{"text":"High"}]],[[{"text":"R3: able but unwilling or insecure"}],[{"text":"S3 Participating","bold":true},{"text":" (supporting)"}],[{"text":"Low"}],[{"text":"High"}]],[[{"text":"R4: able and willing, confident"}],[{"text":"S4 Delegating","bold":true}],[{"text":"Low"}],[{"text":"Low"}]]]},{"type":"paragraph","text":[{"text":"Path-goal theory (Robert House, 1971):","bold":true},{"text":" the leader's job is to "},{"text":"clarify the paths to goals and remove obstacles","bold":true},{"text":" for followers. "},{"text":"4 styles:","bold":true},{"text":" "},{"text":"directive, supportive, participative, achievement-oriented","bold":true},{"text":". The right one depends on follower characteristics and the task environment."}]},{"type":"paragraph","text":[{"text":"Vroom-Yetton normative decision model (1973):","bold":true},{"text":" how far to let followers "},{"text":"participate in a decision","bold":true},{"text":", from deciding alone (autocratic) through consulting to group decision, chosen by answering questions about decision quality and follower acceptance."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Follower maturity or readiness\" is a Hersey and Blanchard idea, "},{"text":"not","bold":true},{"text":" one of Fiedler's three factors."}]},{"text":[{"text":"A fresh graduate trainee in a Port Harcourt firm, unable to do a new task and unsure of himself, is R1, so use "},{"text":"telling","bold":true},{"text":". A skilled, confident senior accountant keen to own month-end close is R4, so use "},{"text":"delegating","bold":true},{"text":"."}]},{"text":[{"text":"Path-goal styles are "},{"text":"not","bold":true},{"text":" coercive, autocratic or bureaucratic. Path-goal is "},{"text":"not","bold":true},{"text":" about applying reward and punishment."}]},{"text":[{"text":"Classification trap: Fiedler, Hersey-Blanchard, path-goal and Vroom are contingency theories; Ohio State, Michigan, Iowa and the Grid are behavioural; Great Man is trait."}]}]}]},{"number":"1.5","title":"Contemporary theories of leadership","mustKnow":[{"type":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 5, $study_guide$"list","ordered":false,"items":[{"text":[{"text":"James MacGregor Burns (1978)","bold":true},{"text":", a political scientist, first distinguished "},{"text":"transforming","bold":true},{"text":" from "},{"text":"transactional","bold":true},{"text":" leadership. "},{"text":"Bernard Bass (1985)","bold":true},{"text":" expanded both. Max "},{"text":"Weber (1947)","bold":true},{"text":" is credited with bringing the transactional notion into the leadership field."}]},{"text":[{"text":"Transformational:","bold":true},{"text":" empowers and inspires followers to go beyond self-interest and achieve personal and organisational goals. "},{"text":"4 I's:","bold":true},{"text":" (1) "},{"text":"idealised influence (charisma)","bold":true},{"text":", (2) "},{"text":"inspirational motivation","bold":true},{"text":", (3) "},{"text":"intellectual stimulation","bold":true},{"text":", (4) "},{"text":"individualised consideration","bold":true},{"text":"."}]},{"text":[{"text":"Transactional:","bold":true},{"text":" based on "},{"text":"exchange","bold":true},{"text":": rewards for good performance, sanctions for poor. "},{"text":"3 elements:","bold":true},{"text":" (1) "},{"text":"contingent reward","bold":true},{"text":", (2) "},{"text":"management by exception-active","bold":true},{"text":", (3) "},{"text":"management by exception-passive","bold":true},{"text":"."}]},{"text":[{"text":"Laissez-faire:","bold":true},{"text":" \"leave it alone\"; non-leadership."}]},{"text":[{"text":"Charismatic:","bold":true},{"text":" influence through the leader's personality, vision and role-modelling (Weber's idea of charisma; developed by Robert House, 1976)."}]},{"text":[{"text":"Servant:","bold":true},{"text":" puts followers' needs and growth first (\"people first\"). "},{"text":"Robert Greenleaf (1970)","bold":true},{"text":"."}]},{"text":[{"text":"Authentic:","bold":true},{"text":" self-awareness, relational transparency, balanced processing, strong moral perspective."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Transformational leadership drives reform and builds a strong culture, but risks over-dependence on charismatic leaders. Transactional leadership gives order and clear expectations but discourages innovation and is short-term. Management by exception-passive (acting only when problems become serious) is harmful."}]},{"text":[{"text":"Do not confuse Burns (transforming leadership, 1978) with "},{"text":"Robert Kelley","bold":true},{"text":" (followership), "},{"text":"Fred Fiedler","bold":true},{"text":" (contingency) or "},{"text":"Robert Blake","bold":true},{"text":" (Managerial Grid)."}]}]}]},{"number":"1.6","title":"Qualities, characteristics, functions and roles","mustKnow":[{"type":"paragraph","text":[{"text":"Qualities of an effective leader:","bold":true},{"text":" decisive; has a "},{"text":"vision","bold":true},{"text":"; empathetic, with conceptual skills, understandable; interpersonal skill."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Vision:","bold":true},{"text":" a "},{"text":"mental picture","bold":true},{"text":" of what someone aims to achieve within a time frame, given constraints. In leadership, vision serves to "},{"text":"provide long-term direction","bold":true},{"text":" for the group. From broadest to most concrete: "},{"text":"vision, goal, objective","bold":true},{"text":". Example: vision = quality education; goal = university education; objective = a four-year course."}]}]},{"type":"paragraph","text":[{"text":"Characteristics of effective leaders (6):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Vision and strategic thinking:","bold":true},{"text":" long-term goals, anticipating risks, spotting trends, aligning resources."}]},{"text":[{"text":"Integrity and ethical responsibility:","bold":true},{"text":" the foundation of "},{"text":"credibility","bold":true},{"text":"; avoiding corruption and abuse of power."}]},{"text":[{"text":"Communication skills:","bold":true},{"text":" enhances cooperation and reduces misunderstandings."}]},{"text":[{"text":"Emotional intelligence:","bold":true},{"text":" "},{"text":"understanding and managing one's own emotions while recognising the feelings of others","bold":true},{"text":"; handles stress, resolves conflict constructively, shows empathy."}]},{"text":[{"text":"Adaptability and innovation:","bold":true},{"text":" supports "},{"text":"institutional resilience","bold":true},{"text":"."}]},{"text":[{"text":"Accountability and responsibility:","bold":true},{"text":" evaluating outcomes honestly, admitting mistakes."}]}]},{"type":"paragraph","text":[{"text":"Core components (functions) of leadership (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Providing direction:","bold":true},{"text":" vision, achievable objectives, clarifying roles, aligning efforts."}]},{"text":[{"text":"Motivating followers","bold":true},{"text":" (the motivating and inspiring function: getting people to work willingly towards a shared vision): recognising achievements, meaningful goals, supportive environment, empathy and fairness, trust."}]},{"text":[{"text":"Making decisions:","bold":true},{"text":" critical thinking, stakeholder consultation, evaluating alternatives, risk assessment, accountability."}]},{"text":[{"text":"Maintaining ethical standards:","bold":true},{"text":" transparency, fairness and justice, no corruption, respect for diversity and human rights, responsible use of resources."}]},{"text":[{"text":"Managing change and conflict:","bold":true},{"text":" clear communication, dialogue, addressing resistance, negotiating, stability."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Roles of a leader:","bold":true},{"text":" be "},{"text":"firm and decisive","bold":true},{"text":"; "},{"text":"bring people together","bold":true},{"text":". "},{"text":"Leadership role","bold":true},{"text":" = the "},{"text":"b$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 6, $study_guide$ehaviours expected of a leader","bold":true},{"text":" in an organisational or social context. The "},{"text":"directing","bold":true},{"text":" function = "},{"text":"motivating and guiding","bold":true},{"text":" subordinates."}]}]},{"type":"paragraph","text":[{"text":"Leadership challenges in governance (5):","bold":true}]},{"type":"table","header":[[{"text":"Challenge"}],[{"text":"Meaning or effect"}],[{"text":"Leadership response"}]],"rows":[[[{"text":"Corruption and misuse of power"}],[{"text":"Authority used for personal gain"}],[{"text":"Accountability, transparency, ethics"}]],[[{"text":"Lack of transparency"}],[{"text":"Suspicion, low participation"}],[{"text":"Open channels, "},{"text":"public reporting","bold":true},{"text":", inclusive talks"}]],[[{"text":"Weak institutions"}],[{"text":"Poor service; reliance on "},{"text":"informal networks","bold":true}],[{"text":"Reform, capacity building"}]],[[{"text":"Political interference"}],[{"text":"Partisan pressure; lower autonomy"}],[{"text":"Professional ethics, safeguards, "},{"text":"merit-based decisions","bold":true}]],[[{"text":"Low citizen trust"}],[{"text":"Caused by scandals, poor service, no accountability"}],[{"text":"Integrity, "},{"text":"tangible results","bold":true},{"text":", participation"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Without direction, organisations suffer "},{"text":"confusion, inefficiency and conflict","bold":true},{"text":". Good conflict management "},{"text":"prevents social unrest and promotes inclusive decision-making","bold":true},{"text":". Ethical failures cause "},{"text":"governance crises and institutional breakdown","bold":true},{"text":"."}]},{"text":[{"text":"Odd-one-out traps: preparing statutory financial statements is not a core component; relying only on instructions is not motivating; choosing the first option to save time is not good decision-making; hiding decisions is not ethical; shifting blame under stress is not emotional intelligence; authoritarian imposition of views or keeping away from subordinates is not a quality of a leader."}]},{"text":[{"text":"Matching cases: a Lagos MD setting a five-year vision and quarterly objectives = "},{"text":"providing direction","bold":true},{"text":". A commissioner holding town halls and negotiating a phased levy compromise = "},{"text":"managing change and conflict","bold":true},{"text":". An Ibadan CEO studying trends before investing ₦500 million = "},{"text":"vision and strategic thinking","bold":true},{"text":". A registrar admitting a portal crash was poorly planned = "},{"text":"accountability and responsibility","bold":true},{"text":". A head deciding firmly the same afternoon = "},{"text":"decisiveness","bold":true},{"text":". An Abuja MD ending a feud between sales and finance = "},{"text":"bringing people together","bold":true},{"text":". A senator pushing party loyalists for agency jobs = "},{"text":"political interference","bold":true},{"text":". A council hiding its ₦2 billion budget needs "},{"text":"public reporting systems","bold":true},{"text":". Delivering tangible results "},{"text":"builds","bold":true},{"text":" trust; it is never a cause of low trust."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership = the process of influencing others to achieve shared goals; relational and dynamic; rests on trust, communication, legitimacy, shared commitment."}]},{"text":[{"text":"Leadership = vision and change; management = control and complexity."}]},{"text":[{"text":"Power (intelligence, wealth, beauty) versus authority (right to command, conferred by the board); authority must be clear, feasible, consistent, capable of being carried out."}]},{"text":[{"text":"French and Raven: legitimate, reward, coercive, expert, referent."}]},{"text":[{"text":"Trait (Great Man): physical, intelligence, task-related, personality; limits: no basis for comparison, ignores situation."}]},{"text":[{"text":"Behavioural: Iowa (Lewin), Ohio State (initiating structure, consideration), Michigan (employee- vs job-centred), Grid (9,9 team; 1,9 country club)."}]},{"text":[{"text":"Contingency: Fiedler (LPC; 3 factors), Hersey-Blanchard (telling, selling, participating, delegating), House path-goal (4 styles), Vroom."}]},{"text":[{"text":"Burns 1978, Bass 1985: transformational (4 I's) and transactional (3 elements); Greenleaf servant."}]},{"text":[{"text":"5 core components; 6 characteristics; roles: decisive, bring people together; 5 governance challenges."}]}]}],"theory":{"itemId":"feb19c9b-c485-51b7-b062-d972d8bfb77e","question":[{"type":"paragraph","text":[{"text":"A Nigerian bank manager has excellent relations with her team, the task is highly structured, and she holds strong formal power to hire, reward and discipline. Using Fiedler's model, which type of leader suits this situation best, and why?"}]}]},"practice":[{"topic":"An Overview of Leadership","named":false}]}},{"kind":"note","itemId":"468dcfcc-53fd-5f44-b605-e71a333a4ffc","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Leadership Approaches and Practices","body":"What leadership style is and what shapes it; the four traditional styles (plus paternalistic); the contemporary styles, the four dimensions of transformational and three elements of transactional leadership; governance styles and their best contexts; leadership philosophy and the four moral leadership approaches; the seven moral leadership practices; the classical moral philosophies (teleology, egoism, utilitarianism, deontology, virtue ethics, relativism, justice) and ethical dilemmas.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"What leadership style is and what shapes it; the four traditional styles (plus paternalistic); the contemporary styles, the four dimensions of transformational and three elements of transactional leadership; governance styles and their best contexts; leadership philosophy and the four moral leaders$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 7, $study_guide$hip approaches; the seven moral leadership practices; the classical moral philosophies (teleology, egoism, utilitarianism, deontology, virtue ethics, relativism, justice) and ethical dilemmas."}],"lessons":[{"number":"2.1","title":"Leadership style and what shapes it","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Origin:","bold":true},{"text":" leadership as a concept developed in the "},{"text":"20th century","bold":true},{"text":" as an offshoot of "},{"text":"scientific management principles","bold":true},{"text":" (the idea that workers can be scientifically observed to improve their effectiveness and performance). Every organisation (large or small, public or private, manufacturing or service) needs effective leaders."}]},{"text":[{"text":"Leadership style:","bold":true},{"text":" the way a leader provides direction, implements plans and motivates people; essentially the way the leader influences followers towards a common goal. Also: the "},{"text":"patterns of thinking, feeling and behaviour","bold":true},{"text":" that people in executive positions use to handle the affairs of employees and organisations. Style is synonymous with the leader's behaviour or practices."}]},{"text":[{"text":"There is "},{"text":"no one best style","bold":true},{"text":". Leaders adjust style to the situation and must know when to use each one."}]},{"text":[{"text":"3 issues that influence the style a leader adopts:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The manager's "},{"text":"individual characteristics","bold":true},{"text":" (personality, knowledge, values, ethics, experience)."}]},{"text":[{"text":"The "},{"text":"employees","bold":true},{"text":" being supervised."}]},{"text":[{"text":"The "},{"text":"organisation","bold":true},{"text":" (traditions, values, philosophy)."}]}]}]},{"text":[{"text":"4 factors on which leadership style depends","bold":true},{"text":" (the governance view): the "},{"text":"environment","bold":true},{"text":", the "},{"text":"leader","bold":true},{"text":", the "},{"text":"followers","bold":true},{"text":", the "},{"text":"objective or goal","bold":true},{"text":"."}]},{"text":[{"text":"Task-oriented leadership:","bold":true},{"text":" structuring tasks, clarifying roles, setting standards, monitoring performance."}]},{"text":[{"text":"Relationship-oriented leadership:","bold":true},{"text":" interpersonal support, trust, concern for people's welfare."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Things that do "},{"text":"not","bold":true},{"text":" shape style in exam options: the company's daily share price, the leader's ethnic origin, age, salary, office size, logo or founding date."}]},{"text":[{"text":"If a manager gives step-by-step instructions to untrained interns but lets senior engineers decide for themselves, with the same goal and workplace, the factor at work is "},{"text":"the followers","bold":true},{"text":"."}]},{"text":[{"text":"Situational leadership","bold":true},{"text":" (Hersey and Blanchard) assumes leaders can "},{"text":"adjust their style flexibly","bold":true},{"text":" to task complexity and follower capability (readiness). It is not a fixed style."}]},{"text":[{"text":"Shared (distributed) leadership:","bold":true},{"text":" leadership roles are "},{"text":"distributed among group members","bold":true},{"text":", not restricted to top management."}]},{"text":[{"text":"Cultural leadership:","bold":true},{"text":" leadership influence that "},{"text":"shapes organisational norms","bold":true},{"text":", values and culture."}]},{"text":[{"text":"Task-oriented maps to Ohio State's \"initiating structure\"; relationship-oriented maps to \"consideration\" (Topic 1)."}]}]}]},{"number":"2.2","title":"Traditional leadership styles","mustKnow":[{"type":"paragraph","text":[{"text":"4 traditional styles:","bold":true},{"text":" (1) democratic or participative, (2) autocratic or authoritarian, (3) bureaucratic, (4) laissez-faire. Paternalistic is also treated as a traditional style."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Democratic (participative):","bold":true},{"text":" invites employees into decision-making; keeps subordinates informed; leader is a "},{"text":"coach who has the final say","bold":true},{"text":" but collects input first. Largely the "},{"text":"most effective","bold":true},{"text":" style, because the leader gives direction and also participates. Yields "},{"text":"high productivity over long periods","bold":true},{"text":" because employees value the "},{"text":"trust","bold":true},{"text":" they receive and respond with cooperation, team spirit and commitment."}]},{"text":[{"text":"Autocratic (authoritarian):","bold":true},{"text":" founded on the "},{"text":"classical approach","bold":true},{"text":"; leader keeps as much power and decision-making authority as possible; "},{"text":"unilateral decisions","bold":true},{"text":" with little or no group input; clear expectations of what, when and how; individual control based on the leader's own ideas, opinions and experience."}]},{"text":[{"text":"Bureaucratic:","bold":true},{"text":" strict adherence to company "},{"text":"policy and laid-down procedure","bold":true},{"text":"; anything outside the policy needs "},{"text":"express approval from management","bold":true},{"text":"; the leader acts like a "},{"text":"regulatory or compliance officer","bold":true},{"text":"."}]},{"text":[{"text":"Laissez-faire (delegative):","bold":true},{"text":" French for "},{"text":"\"leave it alone\"","bold":true},{"text":"; hands-off; little or no direction; "},{"text":"maximum autonomy","bold":true},{"text":"; also called \"non-leadership\" or "},{"text":"absent","bold":true},{"text":" leadership."}]},{"text":[{"text":"Paternalistic:","bold":true},{"text":" leader acts like a parent, deciding in what he believes is the staff's best interest and caring for their $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 8, $study_guide$welfare, in return for loyalty and obedience."}]}]},{"type":"paragraph","text":[{"text":"Bureaucratic style is effective when (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Staff perform routine tasks over and over."}]},{"text":[{"text":"Employees need to understand certain principles or processes."}]},{"text":[{"text":"Employees work with unsafe or delicate equipment needing fixed procedures."}]},{"text":[{"text":"Safety training is being conducted."}]},{"text":[{"text":"Employees perform tasks that involve handling cash."}]}]},{"type":"paragraph","text":[{"text":"Laissez-faire is characterised by (4):","bold":true},{"text":" minimal guidance from leaders; wide-ranging freedom for subordinates to decide; leaders provide the tools and resources required; subordinates solve problems on their own, individually or collectively."}]},{"type":"table","header":[[{"text":"Style"}],[{"text":"Who decides"}],[{"text":"Merit"}],[{"text":"Demerit"}]],"rows":[[[{"text":"Autocratic"}],[{"text":"Leader alone; one-way communication"}],[{"text":"Things get done quickly"}],[{"text":"Hurts morale"}]],[[{"text":"Democratic"}],[{"text":"Leader after consulting; two-way communication"}],[{"text":"Workers motivated and feel recognised"}],[{"text":"Slow decisions"}]],[[{"text":"Bureaucratic"}],[{"text":"The rulebook; approval from top"}],[{"text":"Consistency, safety, control"}],[{"text":"Rigid; poor for new problems"}]],[[{"text":"Laissez-faire"}],[{"text":"Followers"}],[{"text":"Creativity, initiative, entrepreneurial mindset"}],[{"text":"No direction; drift"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Bank tellers in Abuja counting about ₦40 million daily under fixed reconciliation rules suit "},{"text":"bureaucratic","bold":true},{"text":" supervision. Bureaucratic style is "},{"text":"not","bold":true},{"text":" effective where staff must improvise creative solutions to new, non-routine problems."}]},{"text":[{"text":"Laissez-faire works when subordinates are "},{"text":"highly skilled, motivated and able to work on their own","bold":true},{"text":", not when they are new or unwilling. In practice many laissez-faire leaders "},{"text":"remain open and accessible","bold":true},{"text":" for consultation and feedback; close supervision of every task is the opposite of laissez-faire."}]},{"text":[{"text":"Autocrats lead by coercion, are fault-finders rather than coaches, and believe in give-and-take (reward and punishment)."}]},{"text":[{"text":"Paternalism is common in Nigerian family-owned businesses where the owner is a \"father figure\"; its risk is dependence and favouritism."}]},{"text":[{"text":"Trap: "},{"text":"authentic","bold":true},{"text":", transformational and transactional are "},{"text":"not","bold":true},{"text":" traditional styles."}]}]}]},{"number":"2.3","title":"Contemporary styles: transformational and transactional","mustKnow":[{"type":"paragraph","text":[{"text":"3 contemporary styles in this course:","bold":true},{"text":" transformational, transactional, laissez-faire. "},{"text":"Laissez-faire is the one style in both","bold":true},{"text":" the traditional and contemporary lists. Other modern approaches: authentic, servant, adaptive, distributed (shared), ethical leadership. Autocratic is "},{"text":"not","bold":true},{"text":" contemporary."}]},{"type":"paragraph","text":[{"text":"Transformational leadership:","bold":true},{"text":" builds strong team performance by "},{"text":"empowering and motivating","bold":true},{"text":" subordinates to reach personal and organisational goals; inspires new ways of working, risk-taking and solutions; appeals to "},{"text":"higher values, purpose and a shared vision","bold":true},{"text":"; inspires followers to "},{"text":"exceed self-interest","bold":true},{"text":" for the good of the group."}]},{"type":"paragraph","text":[{"text":"4 dimensions (the \"4 I's\"):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Idealised influence (charisma):","bold":true},{"text":" the "},{"text":"most vital element","bold":true},{"text":"; leader is a "},{"text":"good role model","bold":true},{"text":", becomes valued, appreciated and trusted through personality and the beliefs he upholds."}]},{"text":[{"text":"Inspirational motivation:","bold":true},{"text":" engaging, optimistic talk about future goals; challenges staff to high moral standards; clear expression of what must be achieved."}]},{"text":[{"text":"Intellectual stimulation:","bold":true},{"text":" encourages followers to question established conventions, reframe problems and try new approaches."}]},{"text":[{"text":"Individualised consideration:","bold":true},{"text":" concern for each follower's needs; tailored coaching and a supportive climate."}]}]},{"type":"paragraph","text":[{"text":"Transactional leadership:","bold":true},{"text":" based on "},{"text":"exchange","bold":true},{"text":": rewards for good performance, sanctions for poor performance; sets rules, focuses on goals, coordinates effort. Credited to "},{"text":"Max Weber (1947)","bold":true},{"text":", later "},{"text":"expanded by Bernard Bass (1985)","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"3 elements:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Contingent reward:","bold":true},{"text":" what employees must do to qualify for rewards, with punishment when targets are missed."}]},{"text":[{"text":"Management by exception-active:","bold":true},{"text":" leader "},{"text":"continuously monitors","bold":true},{"text":" each follower's performance and corrects deviations early."}]},{"text":[{"text":"Management by exception-passive:","bold":true},{"text":" leader "},{"text":"intervenes only when problems become serious","bold":true},{"text":" or mistakes occur; described as harmful."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Conti$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 9, $study_guide$ngent reward","bold":true},{"text":" belongs to transactional leadership; it is "},{"text":"never","bold":true},{"text":" a transformational dimension. "},{"text":"Intellectual stimulation","bold":true},{"text":", individualised consideration and inspirational motivation are "},{"text":"never","bold":true},{"text":" transactional elements."}]},{"text":[{"text":"Matching scenarios: a Yaba start-up manager urging her team to question assumptions = "},{"text":"intellectual stimulation","bold":true},{"text":"; a head of department coaching each person separately = "},{"text":"individualised consideration","bold":true},{"text":"; a CEO's optimistic rally speech demanding high moral standards = "},{"text":"inspirational motivation","bold":true},{"text":"; a leader trusted as a role model = "},{"text":"idealised influence","bold":true},{"text":"."}]},{"text":[{"text":"A supervisor checking output all day = "},{"text":"MBE-active","bold":true},{"text":"; a branch manager who acts only when a complaint reaches head office = "},{"text":"MBE-passive","bold":true},{"text":"."}]},{"text":[{"text":"Influence through inspiration differs from control because it relies on "},{"text":"emotional and value-based appeal","bold":true},{"text":", not procedures or enforcement."}]},{"text":[{"text":"James MacGregor Burns (1978)","bold":true},{"text":" first contrasted transforming and transactional political leadership; "},{"text":"Bass (1985)","bold":true},{"text":" developed both into the full model."}]}]}]},{"number":"2.4","title":"Leadership styles in governance","mustKnow":[{"type":"table","header":[[{"text":"Style"}],[{"text":"Decision approach"}],[{"text":"Strengths"}],[{"text":"Limitations"}],[{"text":"Best contexts"}]],"rows":[[[{"text":"Democratic"}],[{"text":"Consultative, collective"}],[{"text":"Trust, legitimacy, innovation, civic engagement"}],[{"text":"Slower; conflict; needs skilled facilitation"}],[{"text":"Democratic institutions, universities, policy consultations, community governance"}]],[[{"text":"Transformational"}],[{"text":"Vision-driven"}],[{"text":"Drives innovation and reform; strong culture; social change"}],[{"text":"Vision may overshadow implementation; "},{"text":"overdependence on a charismatic leader","bold":true}],[{"text":"National reforms","bold":true},{"text":", organisational change, development initiatives"}]],[[{"text":"Transactional"}],[{"text":"Structured, rule-based"}],[{"text":"Order, efficiency, clear expectations"}],[{"text":"Discourages innovation; compliance over inspiration; low emotional engagement"}],[{"text":"Bureaucratic systems, public administration, regulatory agencies","bold":true}]],[[{"text":"Authoritarian"}],[{"text":"Leader-controlled"}],[{"text":"Fast decisions; clear direction in emergencies; control"}],[{"text":"Abuse of power; low participation; loss of trust"}],[{"text":"Emergencies","bold":true},{"text":", military operations, crisis management"}]],[[{"text":"Servant"}],[{"text":"Consultative, value-driven"}],[{"text":"Trust, ethical governance, community participation, social cohesion"}],[{"text":"Perceived as weak in hierarchical settings","bold":true},{"text":"; slower"}],[{"text":"Public service, NGOs, education, community development"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Servant leadership","bold":true},{"text":" (Robert "},{"text":"Greenleaf","bold":true},{"text":"): the leader's primary obligation is "},{"text":"serving the needs of followers and the community above self-interest","bold":true},{"text":"; emphasis on "},{"text":"follower development, well-being and empowerment","bold":true},{"text":" (including self-leadership)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sudden Lagos flash floods requiring evacuation within hours call for "},{"text":"authoritarian","bold":true},{"text":" leadership: speed matters more than consultation."}]},{"text":[{"text":"Democratic leadership's key features: open communication, collective decision-making, respect for diverse opinions, transparency, delegation."}]},{"text":[{"text":"Transactional features: performance monitoring, clear rules, reward and punishment, short-term goals."}]}]}]},{"number":"2.5","title":"Leadership philosophy and moral leadership","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Moral philosophy","bold":true},{"text":" is the "},{"text":"ethical foundation","bold":true},{"text":" of leadership: it guides leaders to put "},{"text":"purpose, integrity and service","bold":true},{"text":" first in decisions and in how they treat people."}]},{"text":[{"text":"Leadership philosophy:","bold":true},{"text":" a foundational framework setting out an individual's "},{"text":"core beliefs, values and principles","bold":true},{"text":" about leadership. It acts as a "},{"text":"compass","bold":true},{"text":" guiding decisions, behaviour and interactions."}]},{"text":[{"text":"4 elements of a leadership philosophy:","bold":true},{"text":" theory, attitude, guiding principles, behaviour."}]}]},{"type":"paragraph","text":[{"text":"4 leadership approaches rooted in moral philosophy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ethical leadership:","bold":true},{"text":" respect, accountability, honesty, justice and service, so decisions benefit employees, customers, investors, suppliers, regulators and communities."}]},{"text":[{"text":"Servant leadership:","bold":true},{"text":" puts subordinates' needs and growth first (\"people first\")."}]},{"text":[{"text":"Authentic leadership:","bold":true},{"text":" "},{"text":"self-awareness, relational transparency, balanced processing, strong moral perspective","bold":true},{"text":"; influence from credibility, personal values and consistency rather than formal authority."}]},{"text":[{"text":"Virtuous leadership:","bold":true},{"text":" character traits of "},{"text":"courage, integrity, humility, compassion and wisdom","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 10, $study_guide$d":true},{"text":", guided by moral excellence."}]}]},{"type":"paragraph","text":[{"text":"4 ways moral philosophy influences leadership:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Decision-making:","bold":true},{"text":" a framework (fairness, justice, empathy) for choices aligned with "},{"text":"ethical values rather than expediency","bold":true},{"text":"."}]},{"text":[{"text":"Trust and credibility:","bold":true},{"text":" ethical, transparent leaders earn deeper trust and respect."}]},{"text":[{"text":"Purpose-driven action:","bold":true},{"text":" links leadership to a wider purpose, showing what is right and good."}]},{"text":[{"text":"Human-centred approach:","bold":true},{"text":" puts people at the centre, recognising their humanity, aspirations and concerns; teams become more engaged and loyal."}]}]},{"type":"paragraph","text":[{"text":"7 moral leadership practices:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Start with a pause:","bold":true},{"text":" reflect, reconnect with moral commitments, rethink, reimagine."}]},{"text":[{"text":"See the humanity in everyone:","bold":true},{"text":" people are "},{"text":"ends, not means","bold":true},{"text":"; learn their hopes and struggles."}]},{"text":[{"text":"Foster freedom:","bold":true},{"text":" a culture of interdependence and responsibility, shared values, support for informed risks."}]},{"text":[{"text":"Demonstrate humility:","bold":true},{"text":" confident when warranted, admit the limits of one's knowledge, make amends for mistakes."}]},{"text":[{"text":"Uphold ethical standards:","bold":true},{"text":" model integrity even when unpopular; testing situations are "},{"text":"opportunities to reveal what one most values","bold":true},{"text":", not constraints."}]},{"text":[{"text":"Seek the truth:","bold":true},{"text":" sincere, rigorous effort to find the truth; weigh multiple perspectives."}]},{"text":[{"text":"Act with courage:","bold":true},{"text":" never trade principles for short-term gain; indifference is the greatest risk."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Bureaucratic","bold":true},{"text":" leadership is "},{"text":"not","bold":true},{"text":" a moral-philosophy approach. Remuneration is "},{"text":"not","bold":true},{"text":" an element of a leadership philosophy."}]},{"text":[{"text":"A managing director who publicly admits the limits of his knowledge after a failed decision = "},{"text":"demonstrate humility","bold":true},{"text":". A procurement director refusing a ₦30 million \"gift\" despite angry board members = "},{"text":"act with courage","bold":true},{"text":"."}]}]}]},{"number":"2.6","title":"Moral philosophies and ethical dilemmas","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Moral philosophy:","bold":true},{"text":" the principles or rules people use to decide what is right or wrong."}]},{"text":[{"text":"Teleology (consequentialism):","bold":true},{"text":" an act is right if it produces a desired result; rightness is judged "},{"text":"solely by consequences","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Egoism:","bold":true},{"text":" right = what maximises "},{"text":"one's own self-interest","bold":true},{"text":". Enlightened egoism also considers others' well-being where it serves long-term self-interest."}]},{"text":[{"text":"Utilitarianism","bold":true},{"text":" (Jeremy "},{"text":"Bentham","bold":true},{"text":", John Stuart "},{"text":"Mill","bold":true},{"text":"): right = "},{"text":"the greatest good for the greatest number","bold":true},{"text":". "},{"text":"Rule","bold":true},{"text":" utilitarians follow rules that usually maximise good; "},{"text":"act","bold":true},{"text":" utilitarians judge each act."}]}]}]},{"text":[{"text":"Deontology","bold":true},{"text":" (Immanuel "},{"text":"Kant","bold":true},{"text":"): focus on "},{"text":"duties, rights and principles regardless of outcomes","bold":true},{"text":"; "},{"text":"fairness and moral duty","bold":true},{"text":". Kant's "},{"text":"categorical imperative","bold":true},{"text":": act only on a rule you would want to become a universal law; treat people always as ends, never merely as means."}]},{"text":[{"text":"Virtue ethics","bold":true},{"text":" (Aristotle): good conduct flows from the "},{"text":"character and virtues","bold":true},{"text":" of the person (courage, honesty, prudence, justice)."}]},{"text":[{"text":"Relativism:","bold":true},{"text":" moral standards are judged by the individual or "},{"text":"cultural context","bold":true},{"text":"; no universal rule."}]},{"text":[{"text":"Ethical absolutism:","bold":true},{"text":" moral rules are "},{"text":"unbreakable in every situation","bold":true},{"text":" (the opposite of relativism and situational ethics)."}]},{"text":[{"text":"Justice:","bold":true},{"text":" fairness. "},{"text":"Distributive","bold":true},{"text":" (fair share of outcomes), "},{"text":"procedural","bold":true},{"text":" (fair process), "},{"text":"interactional","bold":true},{"text":" (fair treatment and communication)."}]},{"text":[{"text":"Ethical dilemma:","bold":true},{"text":" a situation with two or more choices, each carrying ethical costs, where no option is clearly right."}]}]},{"type":"table","header":[[{"text":"Philosophy"}],[{"text":"Asks"}],[{"text":"Key name"}]],"rows":[[[{"text":"Utilitarianism"}],[{"text":"Which act gives the greatest good for the greatest number?"}],[{"text":"Bentham, Mill"}]],[[{"text":"Egoism"}],[{"text":"What is best for me?"}],[]],[[{"text":"Deontology"}],[{"text":"What is my duty, whatever the outcome?"}],[{"text":"Kant"}]],[[{"text":"Virtue ethics"}],[{"text":"What would a person of good character do?"}],[{"text":"Aristotle"}]],[[{"text":"Relativism"}],[{"text":"What does my culture or group accept?"}],[]],[[{"text":"Justice"}],[{"text":"Is it fai$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 11, $study_guide$r in outcome, process and treatment?"}],[{"text":"Rawls"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Divine command theory","bold":true},{"text":" (right is what God commands) and "},{"text":"care ethics","bold":true},{"text":" (right is what preserves caring relationships) are distractors, not the answers to \"judged solely by consequences\" or \"moral duty\"."}]},{"text":[{"text":"Dilemma example: a Lagos plant manager can save ₦50 million by quietly skipping a costly safety upgrade. A utilitarian weighs total harm against total gain; a Kantian says protecting workers is a duty whatever the savings; a virtue ethicist asks what an honest, courageous manager would do."}]},{"text":[{"text":"Resolving a dilemma: recognise the issue, gather facts, identify stakeholders and options, test options against the philosophies, decide, act and review."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership style = how a leader directs and influences; no one best style. Shaped by the leader, followers, environment and goal."}]},{"text":[{"text":"Traditional: democratic, autocratic, bureaucratic, laissez-faire (plus paternalistic)."}]},{"text":[{"text":"Contemporary: transformational, transactional, laissez-faire (laissez-faire is in both lists)."}]},{"text":[{"text":"Transformational 4 I's: idealised influence (most vital), inspirational motivation, intellectual stimulation, individualised consideration."}]},{"text":[{"text":"Transactional 3: contingent reward, MBE-active, MBE-passive. Weber 1947, Bass 1985."}]},{"text":[{"text":"Governance: transformational for reforms; transactional for bureaucracies; authoritarian for emergencies; servant for public service."}]},{"text":[{"text":"Leadership philosophy = a compass with 4 elements: theory, attitude, guiding principles, behaviour."}]},{"text":[{"text":"Moral approaches: ethical, servant, authentic, virtuous. Seven moral practices from \"start with a pause\" to \"act with courage\"."}]},{"text":[{"text":"Consequences = teleology/utilitarianism; duty = deontology (Kant); character = virtue ethics; culture = relativism."}]}]}],"theory":{"itemId":"098f5914-29b6-5321-b310-022818cc5c0e","question":[{"type":"paragraph","text":[{"text":"Distinguish transformational from transactional leadership and list the components of each."}]}]},"practice":[{"topic":"Leadership Approaches and Practices","named":false}]}},{"kind":"note","itemId":"54e22175-704f-55b6-bd72-7c71680c213a","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Leadership, Followership, Citizenship and Governance","body":"Leadership as a relational process and its five core components; leadership challenges in governance; followership and Kelley's five follower types; importance and characteristics of effective followers; citizenship, its rights, responsibilities and modes of acquisition; civil society, its examples and functions; how citizens, followers and civil society shape governance in Nigeria.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"Leadership as a relational process and its five core components; leadership challenges in governance; followership and Kelley's five follower types; importance and characteristics of effective followers; citizenship, its rights, responsibilities and modes of acquisition; civil society, its examples and functions; how citizens, followers and civil society shape governance in Nigeria."}],"lessons":[{"number":"3.1","title":"Leadership as a relationship","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership:","bold":true},{"text":" the "},{"text":"process of influencing","bold":true},{"text":" others to achieve "},{"text":"shared goals","bold":true},{"text":" for collective development; it mobilises people, shapes behaviour and coordinates resources."}]},{"text":[{"text":"Leadership is a "},{"text":"relational process","bold":true},{"text":", not a one-person activity: it emerges from interaction between leaders and followers and depends on "},{"text":"trust, communication, legitimacy","bold":true},{"text":" and shared commitment."}]},{"text":[{"text":"Effective governance depends on the interaction of "},{"text":"leaders, followers, citizens and civic institutions","bold":true},{"text":"."}]},{"text":[{"text":"In democracies citizens play "},{"text":"dual roles","bold":true},{"text":": "},{"text":"followers of leaders","bold":true},{"text":" and "},{"text":"active participants in governance","bold":true},{"text":" through civic engagement."}]}]},{"type":"paragraph","text":[{"text":"5 core components of leadership:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Providing direction (vision, objectives, roles)."}]},{"text":[{"text":"Motivating followers (to be effective, innovative, committed)."}]},{"text":[{"text":"Making decisions."}]},{"text":[{"text":"Maintaining ethical standards."}]},{"text":[{"text":"Managing change and conflict."}]}]},{"type":"paragraph","text":[{"text":"6 characteristics of effective leaders:","bold":true},{"text":" vision and strategic thinking; integrity and ethical responsibility; communication skills; emotional intelligence; adaptability and innovation; accountability and responsibility."}]},{"type":"paragraph","text":[{"text":"5 leadership challenges in governance:","bold":true}]},{"type":"table","header":[[{"text":"Challenge"}],[{"text":"Meaning"}],[{"text":"Leadership response"}]],"rows":[[[{"text":"Corruption and misuse of power"}],[{"text":"Authority used for personal gain"}],[{"text":"Accountability systems, transparency, ethical standards"}]],[[{"text":"Lack of transparency"}],[{"text":"Closed decisions, no access to information"}],[{"text":"Open channels, public reporting, inclusive discussions"}]],[[{"text":"Weak institutions"}],[{"text":"No structure, capacity or independence to enforce laws"}],[{"text":"Institutional reform, capacity building"}]],[[{"text":"Political interfe$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 12, $study_guide$rence"}],[{"text":"Outsiders sway decisions for partisan interest"}],[{"text":"Professional ethics, safeguards, merit-based decisions"}]],[[{"text":"Low citizen trust"}],[{"text":"Citizens disengage after scandals or poor service"}],[{"text":"Integrity, tangible results, citizen participation"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Emotional intelligence:","bold":true},{"text":" understanding and managing your own emotions while recognising others'."}]},{"text":[{"text":"Leadership effectiveness "},{"text":"improves","bold":true},{"text":" with "},{"text":"transparent","bold":true},{"text":" communication and "},{"text":"declines","bold":true},{"text":" when followers suffer "},{"text":"chronic disengagement","bold":true},{"text":". Effective leaders recognise that followers have "},{"text":"valuable skills and insights","bold":true},{"text":"."}]},{"text":[{"text":"\"Good leaders must first be good followers\": leadership development "},{"text":"requires understanding followers' perspective, needs and challenges","bold":true},{"text":" before leading."}]},{"text":[{"text":"Leadership style depends on "},{"text":"4 factors: the environment, the leader, the followers and the objective or goal","bold":true},{"text":"; not the leader's ethnic origin, age or salary. A manager who instructs new interns step by step but lets senior engineers decide, with the same goal and workplace, is adjusting to "},{"text":"the followers","bold":true},{"text":"."}]}]}]},{"number":"3.2","title":"Followership and Kelley's model","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Followership:","bold":true},{"text":" the "},{"text":"active role","bold":true},{"text":" individuals play in "},{"text":"supporting, influencing and sometimes challenging","bold":true},{"text":" leaders to achieve shared objectives. Also: the behaviour of people who back leaders while actively contributing to organisational or societal goals."}]},{"text":[{"text":"It emphasises "},{"text":"collaboration, critical thinking and ethical responsibility","bold":true},{"text":"."}]},{"text":[{"text":"Modern view:","bold":true},{"text":" followers are "},{"text":"partners","bold":true},{"text":" in the leadership process, not passive recipients of instructions (the traditional view)."}]},{"text":[{"text":"Leader-follower relationship:","bold":true},{"text":" "},{"text":"dynamic and reciprocal","bold":true},{"text":"; each role influences and depends on the other."}]}]},{"type":"paragraph","text":[{"text":"Kelley's followership model","bold":true},{"text":" (Robert "},{"text":"Kelley","bold":true},{"text":", 1992) classifies followers on "},{"text":"independent (critical) thinking","bold":true},{"text":" and "},{"text":"level of engagement","bold":true},{"text":" (active or passive):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Exemplary (star):","bold":true},{"text":" active "},{"text":"and","bold":true},{"text":" independent thinkers. The "},{"text":"most effective","bold":true},{"text":"."}]},{"text":[{"text":"Conformist:","bold":true},{"text":" active but "},{"text":"unquestioning","bold":true},{"text":" (\"yes-people\")."}]},{"text":[{"text":"Passive:","bold":true},{"text":" "},{"text":"dependent on leaders","bold":true},{"text":" for direction; no initiative."}]},{"text":[{"text":"Alienated:","bold":true},{"text":" "},{"text":"critical but disengaged","bold":true},{"text":"."}]},{"text":[{"text":"Pragmatic:","bold":true},{"text":" "},{"text":"flexible and situational","bold":true},{"text":"; shifts with whatever the situation rewards."}]}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Thinking"}],[{"text":"Engagement"}]],"rows":[[[{"text":"Exemplary"}],[{"text":"Independent"}],[{"text":"Active"}]],[[{"text":"Conformist"}],[{"text":"Dependent"}],[{"text":"Active"}]],[[{"text":"Alienated"}],[{"text":"Independent"}],[{"text":"Passive"}]],[[{"text":"Passive"}],[{"text":"Dependent"}],[{"text":"Passive"}]],[[{"text":"Pragmatic"}],[{"text":"Middle"}],[{"text":"Middle"}]]]},{"type":"paragraph","text":[{"text":"6 importance of followership in governance:","bold":true},{"text":" prevents authoritarian leadership and abuse; encourages democratic participation; enhances institutional performance; strengthens accountability mechanisms; supports policy implementation; encourages organisational stability."}]},{"type":"paragraph","text":[{"text":"6 characteristics of effective followers:","bold":true},{"text":" critical thinking; responsibility; ethical awareness; courage to question unethical practices; teamwork and cooperation; commitment to institutional values."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Scenarios: an accounts officer who works hard but objects, with reasons, to a ₦15 million payment lacking documents = "},{"text":"exemplary","bold":true},{"text":". A worker who obeys every order, even doubtful ones = "},{"text":"conformist","bold":true},{"text":". A clerk who waits to be told everything = "},{"text":"passive","bold":true},{"text":". An officer who criticises privately but refuses to help = "},{"text":"alienated","bold":true},{"text":". A union officer who changes stance with the mood = "},{"text":"pragmatic","bold":true},{"text":"."}]},{"text":[{"text":"\"Charismatic followers\" is "},{"text":"not","bold":true},{"text":" a Kelley type. Kelley's dimensions are "},{"text":"not","bold":true},{"text":" task structure and position power (Fiedler), concern for people and production (Managerial Grid), or ability and willingness (Hersey and Blanchard)."}]},{"text":[{"text":"Followership supports leadership while keeping "},{"text":"personal integrity","bold":true},{"text":", not blind loyalty. In democracies followers have a duty to "},{"text":"scrutinise","bold":true},{"text":" leadership actions."}]},{"text":[{"text":"Effective followership helps organisations because competent followers "},{"text":"co-create $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 13, $study_guide$outcomes and give critical feedback","bold":true},{"text":" leaders need. Active followership "},{"text":"maintains accountability and prevents misuse of power","bold":true},{"text":"."}]},{"text":[{"text":"Followership never \"guarantees that leaders never make mistakes\", and unquestioning loyalty is "},{"text":"not","bold":true},{"text":" a mark of an effective follower."}]},{"text":[{"text":"If staff watch their director divert ₦60 million and stay silent, passive followership "},{"text":"lets misuse of power continue and weakens governance","bold":true},{"text":"."}]}]}]},{"number":"3.3","title":"Citizenship","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Citizenship:","bold":true},{"text":" an individual's "},{"text":"legal membership in a country","bold":true},{"text":", involving "},{"text":"rights, duties and participation in governance and development","bold":true},{"text":". Also: the legal and social relationship between an individual and a state."}]},{"text":[{"text":"3 elements of citizenship:","bold":true},{"text":" legal membership in a country; political participation (voting, advocacy); social responsibilities toward community development."}]},{"text":[{"text":"Citizenship lets people "},{"text":"claim protection under national law","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"5 rights of citizens:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Right to vote and political participation."}]},{"text":[{"text":"Freedom of speech and association."}]},{"text":[{"text":"Access to justice."}]},{"text":[{"text":"Right to education."}]},{"text":[{"text":"Equal protection under the law."}]}]},{"type":"paragraph","text":[{"text":"6 responsibilities of citizens:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Obeying laws."}]},{"text":[{"text":"Paying taxes."}]},{"text":[{"text":"Voting responsibly."}]},{"text":[{"text":"Participating in community activities."}]},{"text":[{"text":"Promoting social harmony."}]},{"text":[{"text":"Holding leaders accountable."}]}]},{"type":"paragraph","text":[{"text":"Types (modes of acquiring) legal citizenship in Nigeria","bold":true},{"text":" (1999 Constitution, Chapter III): by "},{"text":"birth","bold":true},{"text":", by "},{"text":"registration","bold":true},{"text":", by "},{"text":"naturalisation","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Registration","bold":true},{"text":" covers, for example, a foreign woman married to a Nigerian man. "},{"text":"Naturalisation","bold":true},{"text":" is for foreigners who meet residence and other legal conditions. Long residence "},{"text":"alone","bold":true},{"text":" does not make anyone a citizen."}]},{"text":[{"text":"Dual citizenship:","bold":true},{"text":" a Nigerian "},{"text":"by birth","bold":true},{"text":" may hold another citizenship; a citizen by registration or naturalisation who acquires or retains another citizenship forfeits the Nigerian one."}]},{"text":[{"text":"Active citizenship:","bold":true},{"text":" citizens "},{"text":"participating meaningfully","bold":true},{"text":" in governance, policy-making and community affairs and holding leaders accountable. "},{"text":"Passive citizenship","bold":true},{"text":" is mere compliance. Holding office or simply paying tax is not the definition of active citizenship."}]},{"text":[{"text":"Civic responsibility","bold":true},{"text":" includes protecting "},{"text":"public resources","bold":true},{"text":", not elite interests."}]},{"text":[{"text":"Citizenship education","bold":true},{"text":" equips people with knowledge of "},{"text":"rights, responsibilities and civic participation skills","bold":true},{"text":"; it does not teach blind obedience."}]},{"text":[{"text":"Trap: paying taxes and holding leaders accountable are "},{"text":"responsibilities","bold":true},{"text":"; equal protection under the law is a "},{"text":"right","bold":true},{"text":"."}]}]}]},{"number":"3.4","title":"Civil society","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Civil (civic) society:","bold":true},{"text":" voluntary, "},{"text":"non-governmental","bold":true},{"text":" organisations and institutions that "},{"text":"represent citizens' interests and promote accountability","bold":true},{"text":", transparency and citizens' well-being. It is the arena of voluntary associations "},{"text":"outside government and business","bold":true},{"text":", operating "},{"text":"between the state and the private sector","bold":true},{"text":"."}]},{"text":[{"text":"It acts as a "},{"text":"bridge between citizens and the state","bold":true},{"text":" and depends on "},{"text":"voluntary support","bold":true},{"text":" for its sustainability."}]}]},{"type":"paragraph","text":[{"text":"6 examples:","bold":true},{"text":" NGOs; religious bodies; professional associations; labour unions; student organisations; media institutions. Community-based organisations also count."}]},{"type":"paragraph","text":[{"text":"6 functions of civil society:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Advocacy and policy influence."}]},{"text":[{"text":"Civic education."}]},{"text":[{"text":"Election monitoring."}]},{"text":[{"text":"Human rights protection."}]},{"text":[{"text":"Public accountability promotion."}]},{"text":[{"text":"Community development."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nigerian examples: the "},{"text":"Nigeria Labour Congress (NLC)","bold":true},{"text":" campaigning on wages and policy; the "},{"text":"National Association of Nigerian Students (NANS)","bold":true},{"text":"; the Nigerian Bar Association; religious bodies; the press."}]},{"text":[{"text":"A federal ministry is a "},{"text":"public sector entity","bold":true},{"text":", not civil society. Enacting laws (legislature), co$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 14, $study_guide$mmanding the armed forces and collecting taxes are "},{"text":"not","bold":true},{"text":" civil society functions."}]},{"text":[{"text":"NGOs sending observers to polling units and publishing an irregularities report = "},{"text":"election monitoring","bold":true},{"text":". An NGO radio programme in Hausa and Yoruba on constitutional rights = "},{"text":"civic education","bold":true},{"text":"."}]}]}]},{"number":"3.5","title":"Citizenship and governance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Governance:","bold":true},{"text":" the "},{"text":"systems and processes through which authority is exercised and decisions are made","bold":true},{"text":" in public or organisational institutions. It "},{"text":"extends beyond government","bold":true},{"text":" to private organisations, civil society actors and community groups."}]}]},{"type":"paragraph","text":[{"text":"7 elements of good governance:","bold":true},{"text":" transparency; accountability; rule of law; participation; equity and inclusiveness; responsiveness; efficiency and effectiveness."}]},{"type":"paragraph","text":[{"text":"5 roles of citizens in governance:","bold":true},{"text":" voting and electoral participation; public consultations and policy discussions; community advocacy; monitoring public officials; civic activism."}]},{"type":"paragraph","text":[{"text":"5 roles of followership in governance:","bold":true},{"text":" supporting ethical leaders; resisting corruption; participating in decision-making; providing feedback on public policies; upholding institutional standards."}]},{"type":"paragraph","text":[{"text":"Effective governance occurs when (4):","bold":true},{"text":" leaders act ethically and responsibly; followers actively engage and give constructive feedback; citizens participate in democratic processes; civil society promotes accountability and transparency."}]},{"type":"paragraph","text":[{"text":"Weak governance results from (4):","bold":true},{"text":" passive followership; civic apathy; lack of accountability mechanisms; weak institutional structures."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Accountability:","bold":true},{"text":" the obligation of leaders to explain their actions, accept responsibility and face consequences; it ensures "},{"text":"answerability","bold":true},{"text":". "},{"text":"Mechanisms (4):","bold":true},{"text":" performance monitoring, legal oversight, public reporting, institutional checks and balances."}]},{"text":[{"text":"Transparency:","bold":true},{"text":" openness in decisions, access to information, clear communication. "},{"text":"Promotes:","bold":true},{"text":" trust in institutions, reduced corruption, public participation, effective monitoring of leaders. Without it governance is open to "},{"text":"secrecy, inefficiency and abuse of power","bold":true},{"text":"."}]},{"text":[{"text":"Democratic participation forms (5):","bold":true},{"text":" voting, public consultations, civic activism, community engagement, advocacy and policy dialogue. It keeps leaders "},{"text":"responsive","bold":true},{"text":" to citizens and policies in line with public interest."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The link between citizenship and good governance: an "},{"text":"informed, engaged citizenry holds leaders accountable","bold":true},{"text":" and promotes transparency. Citizens influence governance between elections too, not only at election time. Participation enhances "},{"text":"policy responsiveness","bold":true},{"text":"."}]},{"text":[{"text":"Governance quality reflects the "},{"text":"collective actions of leaders and followers","bold":true},{"text":", not the head of government alone."}]},{"text":[{"text":"Nigerian applications (5):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Electoral participation:","bold":true},{"text":" low voter turnout "},{"text":"reduces leadership accountability and legitimacy","bold":true},{"text":"."}]},{"text":[{"text":"Youth participation:","bold":true},{"text":" activism, policy advocacy and community development."}]},{"text":[{"text":"Student governance:","bold":true},{"text":" responsible student leaders and followers improve university administration (a union president who consults students before negotiating hostel fees)."}]},{"text":[{"text":"Community development associations:","bold":true},{"text":" collective, grassroots action (Abeokuta residents paying ₦5,000 per household to repair a culvert)."}]},{"text":[{"text":"Media and civic advocacy:","bold":true},{"text":" investigative journalism exposing diverted funds (₦2.3 billion meant for clinics), followed by campaigns for prosecution."}]}]}]},{"text":[{"text":"Enugu residents tracking a ₦120 million constituency project = "},{"text":"monitoring public officials","bold":true},{"text":". A clerk refusing ₦2 million to push a file = "},{"text":"resisting corruption","bold":true},{"text":". Students answering a survey on a draft hostel policy = "},{"text":"feedback on public policies","bold":true},{"text":". Staff association members on a welfare committee = "},{"text":"participating in decision-making","bold":true},{"text":"."}]},{"text":[{"text":"Do not confuse lists: \"preventing authoritarian leadership, encouraging stability...\" is the "},{"text":"importance","bold":true},{"text":" of followership; \"voting responsibly, obeying laws, paying taxes...\" are citizens' "},{"text":"responsibilities","bold":true},{"text":"; \"advocacy, civic education, election monitoring...\" are civil society "},{"text":"functions","bold":true},{"text":". Bribing officials is "},{"text":"not","bold":true},{"text":" democratic participation."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership = influencing others towards shared goals; a relational process with 5 core components."}]},{"text":[{"text":"Followership = ac$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 15, $study_guide$tive support, influence and challenge; followers are partners."}]},{"text":[{"text":"Kelley (1992): exemplary, conformist, passive, alienated, pragmatic; dimensions are independent thinking and engagement."}]},{"text":[{"text":"Citizenship = legal membership with rights, duties and participation; Nigeria: birth, registration, naturalisation."}]},{"text":[{"text":"5 rights (vote, speech, justice, education, equal protection); 6 responsibilities (laws, taxes, voting, community, harmony, accountability)."}]},{"text":[{"text":"Civil society = voluntary non-governmental bodies between state and private sector; 6 functions."}]},{"text":[{"text":"Governance = systems and processes for exercising authority; 7 elements; extends beyond government."}]},{"text":[{"text":"Weak governance: passive followership, civic apathy, no accountability, weak institutions."}]}]}],"theory":{"itemId":"245ebff8-43a6-5ff8-bdf5-916dbcb39cd6","question":[{"type":"paragraph","text":[{"text":"Name Kelley's five follower types and say which type governance needs most, with a reason."}]}]},"practice":[{"topic":"Leadership, Followership, Citizenship and Governance","named":false}]}},{"kind":"note","itemId":"cb0db6ec-a8e4-5614-83b5-2a81d079dff7","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Social Contract and Ethics","body":"What a social contract is and its examples; Hobbes, Locke, Rousseau and Rawls (books, state of nature, who holds power); social contract ethics and the meaning and principles of ethics; the 8 public sector and 6 private sector ethical issues and their remedies; codes of conduct, corruption and accountability in Nigeria (CCB, CCT, EFCC, ICPC).","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What a social contract is and its examples; Hobbes, Locke, Rousseau and Rawls (books, state of nature, who holds power); social contract ethics and the meaning and principles of ethics; the 8 public sector and 6 private sector ethical issues and their remedies; codes of conduct, corruption and accountability in Nigeria (CCB, CCT, EFCC, ICPC)."}],"lessons":[{"number":"4.1","title":"The social contract: meaning and examples","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social contract:","bold":true},{"text":" when a group of people agree to "},{"text":"give up certain rights","bold":true},{"text":" and "},{"text":"accept a central authority","bold":true},{"text":" in order to "},{"text":"protect their other rights","bold":true},{"text":"."}]},{"text":[{"text":"It is also an "},{"text":"implicit agreement","bold":true},{"text":" among the members of a society to "},{"text":"cooperate for social benefits","bold":true},{"text":", for example by "},{"text":"sacrificing some individual freedom for state protection","bold":true},{"text":" (this is the trade-off at its heart)."}]},{"text":[{"text":"The social contract is "},{"text":"what allows any government to work","bold":true},{"text":", but "},{"text":"government and the social contract are different things","bold":true},{"text":"."}]},{"text":[{"text":"Social contract theory:","bold":true},{"text":" people live together in society in accordance with "},{"text":"an agreement that establishes moral and political rules of behaviour","bold":true},{"text":"."}]},{"text":[{"text":"Theories of the social contract became popular in the "},{"text":"16th, 17th and 18th centuries","bold":true},{"text":" (Thomas "},{"text":"Hobbes","bold":true},{"text":", John "},{"text":"Locke","bold":true},{"text":", Jean-Jacques "},{"text":"Rousseau","bold":true},{"text":") as a means of explaining "},{"text":"the origin of government and the obligations of subjects","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Examples of the social contract","bold":true},{"text":" (grouped so you can remember them):"}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Examples"}]],"rows":[[[{"text":"Political rights and democracy"}],[{"text":"voting, democracy, right to vote, right to run for political office, political rights"}]],[[{"text":"Freedoms"}],[{"text":"constitutional freedoms, freedom of speech, expression, religion, assembly and movement; personal sovereignty; right to privacy"}]],[[{"text":"Legal protection"}],[{"text":"legal rights, right to a fair trial, protection under the law, equal protection under the law"}]],[[{"text":"Economic and social"}],[{"text":"economic rights, right to education, government services, social safety net"}]],[[{"text":"Civic duties"}],[{"text":"civic duty, jury duty, census participation, taxes"}]],[[{"text":"State authority"}],[{"text":"laws, regulations, government authority, emergency measures that override freedoms, international agreements"}]],[[{"text":"Administrative requirements"}],[{"text":"registering births, obtaining government identification"}]],[[{"text":"Business expectations"}],[{"text":"corporate social responsibility, consumer protection, environmental protection"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rights vs duties:","bold":true},{"text":" jury duty, census participation, paying taxes and civic duty are "},{"text":"duties","bold":true},{"text":" you owe; a fair trial, privacy and freedom of religion are "},{"text":"rights","bold":true},{"text":" you receive. An exam may ask which item is a duty: jury duty."}]},{"text":[{"text":"Registering births and getting a National Identification Number","bold":true},{"text":" are listed as "},{"text":"administrative requirements","bold":true},{"text":", not freedoms or economic rights."}]},{"text":[{"text":"Because "},{"text":"CSR, consumer protection and environmental protection","bold":true},{"text":" appear in the list, the social contract also shapes "},{"text":"what society expects of businesses","bold":true},{"text":", not only of governments."}]},{"text":[{"text":"Curfew example:","bold":true},{"text":" during violent unrest a state government imposes a dusk-to-dawn curfew; residents a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 16, $study_guide$ccept a temporary limit on movement so lives and property are protected. That is the social contract (some freedom given up for state protection), and also an example of \"emergency measures that override freedoms\"."}]},{"text":[{"text":"Tax example:","bold":true},{"text":" a Lagos trader pays ₦250,000 in tax a year and expects security, roads and courts in return. That exchange is the social contract."}]},{"text":[{"text":"Breach of the social contract:","bold":true},{"text":" a government that "},{"text":"systematically denies citizens basic rights and public services","bold":true},{"text":" breaks its side of the bargain. Passing tax laws, holding free and fair elections and setting up an independent judiciary are the contract working, not breaches."}]},{"text":[{"text":"The contract is "},{"text":"implicit","bold":true},{"text":": it is not a written document signed by every citizen, not a trade agreement between countries, and not an employment contract with the state."}]}]}]},{"number":"4.2","title":"Hobbes, Locke, Rousseau and Rawls","mustKnow":[{"type":"table","header":[[{"text":"Theorist"}],[{"text":"Main work"}],[{"text":"State of nature"}],[{"text":"Who holds power / key idea"}]],"rows":[[[{"text":"Thomas Hobbes","bold":true},{"text":" (English)"}],[{"text":"Leviathan","italic":true},{"text":" (1651)"}],[{"text":"\"war of all against all\"; life is \""},{"text":"solitary, poor, nasty, brutish and short","bold":true},{"text":"\""}],[{"text":"People surrender their rights to a "},{"text":"strong, absolute sovereign","bold":true},{"text":" that guarantees peace and security"}]],[[{"text":"John Locke","bold":true},{"text":" (English)"}],[{"text":"Two Treatises of Government","italic":true},{"text":" (1689)"}],[{"text":"governed by "},{"text":"natural law and reason","bold":true},{"text":", fairly peaceful but "},{"text":"insecure","bold":true},{"text":" (no impartial judge)"}],[{"text":"Government by "},{"text":"consent","bold":true},{"text":" exists to protect natural rights to "},{"text":"life, liberty and property","bold":true},{"text":"; if it violates them, the people may "},{"text":"resist and replace","bold":true},{"text":" it"}]],[[{"text":"Jean-Jacques Rousseau","bold":true},{"text":" (Geneva-born)"}],[{"text":"The Social Contract","italic":true},{"text":" (1762)"}],[{"text":"people are "},{"text":"free and equal","bold":true},{"text":", later corrupted by society and private property"}],[{"text":"Sovereignty lies with the people; legitimate laws must reflect the "},{"text":"general will","bold":true},{"text":"; legitimacy comes from the "},{"text":"consent and agreement of the governed","bold":true}]],[[{"text":"John Rawls","bold":true},{"text":" (American)"}],[{"text":"A Theory of Justice","italic":true},{"text":" (1971)"}],[{"text":"replaced by the "},{"text":"original position","bold":true},{"text":" behind a "},{"text":"veil of ignorance","bold":true}],[{"text":"Justice as fairness","bold":true},{"text":": rules chosen without knowing your own place in society"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Rawls' two principles of justice:","bold":true},{"text":" (1) "},{"text":"equal basic liberties","bold":true},{"text":" for all; (2) social and economic inequalities are allowed only if they are attached to positions open to all under "},{"text":"fair equality of opportunity","bold":true},{"text":" and benefit the "},{"text":"least advantaged","bold":true},{"text":" (the "},{"text":"difference principle","bold":true},{"text":")."}]},{"text":[{"text":"Classical social contract theorists = Hobbes, Locke, Rousseau. "},{"text":"Not","bold":true},{"text":" social contract theorists: Karl "},{"text":"Marx","bold":true},{"text":", Niccolò "},{"text":"Machiavelli","bold":true},{"text":", Max Weber, and leadership scholars such as Kelley, Bass and Burns."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Hobbes vs Locke:","bold":true},{"text":" Hobbes believed a "},{"text":"powerful sovereign","bold":true},{"text":" was necessary to prevent the brutish state of nature; people keep almost no rights against it. Locke believed people "},{"text":"keep their natural rights","bold":true},{"text":" after forming a government. Trap: \"Locke saw it as a war of all against all\" is reversed; that is Hobbes."}]},{"text":[{"text":"Hobbes vs Rousseau:","bold":true},{"text":" Hobbes favoured an "},{"text":"absolute sovereign","bold":true},{"text":"; Rousseau placed sovereignty in the "},{"text":"general will of the people","bold":true},{"text":"."}]},{"text":[{"text":"Rousseau's famous opening line: \""},{"text":"Man is born free, and everywhere he is in chains.","bold":true},{"text":"\""}]},{"text":[{"text":"Property","bold":true},{"text":" as the foundation of political obligation points to "},{"text":"Locke","bold":true},{"text":"; the "},{"text":"general will","bold":true},{"text":" points to "},{"text":"Rousseau","bold":true},{"text":"; "},{"text":"\"solitary, poor, nasty, brutish and short\"","bold":true},{"text":" and "},{"text":"Leviathan","italic":true},{"text":" point to "},{"text":"Hobbes","bold":true},{"text":"; "},{"text":"veil of ignorance","bold":true},{"text":" points to "},{"text":"Rawls","bold":true},{"text":"."}]},{"text":[{"text":"Divine right of kings, military strength and inherited privilege are the very ideas the social contract theorists replaced with "},{"text":"consent","bold":true},{"text":"."}]},{"text":[{"text":"Locke's right to resist is often linked with later constitutional democracy; in Nigeria the idea that power belongs to the people appears in the 1999 Constitution, which says sovereignty belongs to the people of Nigeria, from whom government derives all its powers and authority."}]}]}]},{"number":"4.3","title":"Social contract ethics, meaning and principles of ethics","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ethics:","bold":true},{"text":" the moral principles and standards t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 17, $study_guide$hat guide what is right and wrong in behaviour and decisions. Leadership ethics guides decision-making by providing "},{"text":"moral principles and standards","bold":true},{"text":"; the ethical dimension of leadership emphasises "},{"text":"moral responsibility and integrity","bold":true},{"text":"."}]},{"text":[{"text":"Social contract ethics","bold":true},{"text":" (contractarian ethics): moral and social rules are justified because rational people "},{"text":"would agree to them","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Key ideas of social contract ethics:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Laws are justified","bold":true},{"text":" when they "},{"text":"align with principles citizens would accept","bold":true},{"text":"."}]},{"text":[{"text":"Goal:","bold":true},{"text":" to make social rules "},{"text":"fair and acceptable","bold":true},{"text":"."}]},{"text":[{"text":"Authority","bold":true},{"text":" of a leader rests on "},{"text":"collective agreement and legitimacy","bold":true},{"text":"."}]},{"text":[{"text":"Rights","bold":true},{"text":" = "},{"text":"mutually recognised protections","bold":true},{"text":"."}]},{"text":[{"text":"Moral obligation","bold":true},{"text":" = a "},{"text":"rationally accepted constraint","bold":true},{"text":"."}]},{"text":[{"text":"Moral rules gain strength from "},{"text":"shared endorsement","bold":true},{"text":"."}]},{"text":[{"text":"Moral norms are sustained through "},{"text":"mutual expectation and trust","bold":true},{"text":"."}]},{"text":[{"text":"Injustice","bold":true},{"text":" occurs when "},{"text":"agreements favour some unfairly","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Principles of ethics","bold":true},{"text":" (in public and organisational life):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Integrity","bold":true},{"text":" 2. "},{"text":"Honesty","bold":true},{"text":" 3. "},{"text":"Accountability","bold":true},{"text":" 4. "},{"text":"Transparency/openness","bold":true},{"text":" 5. "},{"text":"Fairness and justice","bold":true},{"text":" 6. "},{"text":"Objectivity","bold":true},{"text":" (decisions on merit) 7. "},{"text":"Respect","bold":true},{"text":" for persons 8. "},{"text":"Selflessness","bold":true},{"text":" (public interest first) 9. "},{"text":"Responsibility/stewardship","bold":true},{"text":" of resources."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The UK's "},{"text":"Nolan Committee (1995)","bold":true},{"text":" set out seven principles of public life widely used in codes of conduct: "},{"text":"selflessness, integrity, objectivity, accountability, openness, honesty, leadership","bold":true},{"text":"."}]},{"text":[{"text":"Social contract ethics is not based on "},{"text":"personal moral intuition, inherited virtue, religious doctrine, tradition, fear or emotion","bold":true},{"text":". Those are the usual wrong options. Nor are laws justified merely because they \"promote stability regardless of fairness\" or \"preserve existing hierarchies\"."}]},{"text":[{"text":"Rawls fits here: his veil of ignorance is a test for whether rules are fair enough that everyone would accept them."}]},{"text":[{"text":"CSR","bold":true},{"text":" reflects a "},{"text":"stakeholder-oriented","bold":true},{"text":" view: business has responsibilities "},{"text":"beyond profit","bold":true},{"text":", not pure profit maximisation or tax compliance only."}]}]}]},{"number":"4.4","title":"Ethical issues in the public and private sectors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public sector","bold":true},{"text":" ethical issues centre on "},{"text":"abuse of authority for personal gain, conflicts of interest, corruption and failure to act in the public interest","bold":true},{"text":". Bribery, nepotism, mismanagement of public funds and weak accountability "},{"text":"erode public trust","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"8 key ethical issues in the public sector","bold":true},{"text":" (some lists give 7, leaving out data privacy; learn all 8):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Corruption and bribery:","bold":true},{"text":" using public office for private gain: accepting kickbacks, stealing public funds, manipulating contracts."}]},{"text":[{"text":"Conflict of interest:","bold":true},{"text":" officials decide to benefit themselves, family or associates rather than the public."}]},{"text":[{"text":"Nepotism and favouritism:","bold":true},{"text":" hiring, promoting or awarding contracts to friends or family on relationships, not merit."}]},{"text":[{"text":"Misuse of power/authority:","bold":true},{"text":" intimidating, harassing or discriminating against people."}]},{"text":[{"text":"Lack of accountability and transparency:","bold":true},{"text":" concealing information, making fraudulent reports, avoiding scrutiny."}]},{"text":[{"text":"Data privacy violations:","bold":true},{"text":" improper handling of, or unauthorised access to, confidential citizen or government information."}]},{"text":[{"text":"Ethical dilemmas in decision-making:","bold":true},{"text":" choosing between personal values, political pressure and professional responsibilities, often leading to poor administrative judgement."}]},{"text":[{"text":"Low integrity/work ethic:","bold":true},{"text":" absenteeism, laziness, lack of dedication to public service."}]}]},{"type":"paragraph","text":[{"text":"Remedies (4):","bold":true},{"text":" strong "},{"text":"anti-corruption laws","bold":true},{"text":", "},{"text":"whistleblower protection","bold":true},{"text":", improved "},{"text":"transparency","bold":true},{"text":", "},{"text":"merit-based administration","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Private sector","bold":true},{"text":" ethical is$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 18, $study_guide$sues primarily arise from "},{"text":"profit-driven decision-making","bold":true},{"text":", and often stem from "},{"text":"intense pressure for performance, leading to unethical shortcuts","bold":true},{"text":" that risk legal consequences and reputational damage."}]}]},{"type":"paragraph","text":[{"text":"6 key ethical issues in the private sector:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Workplace harassment and discrimination","bold":true},{"text":" (race, gender, religion)."}]},{"text":[{"text":"Conflicts of interest","bold":true},{"text":" (personal interests such as nepotism compromise judgement)."}]},{"text":[{"text":"Data privacy and security","bold":true},{"text":" (misuse or weak protection of customers' personal and financial data)."}]},{"text":[{"text":"Financial integrity and fraud","bold":true},{"text":" (dishonest reporting, bribery, manipulation to hit targets)."}]},{"text":[{"text":"Environmental and social responsibility","bold":true},{"text":" failures (environmental harm; unsafe, unfair labour in the supply chain)."}]},{"text":[{"text":"Anti-competitive behaviour","bold":true},{"text":" (e.g. price-fixing)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why the sectors differ:","bold":true},{"text":" public officials are "},{"text":"stewards of public resources","bold":true},{"text":" and owe "},{"text":"accountability to all citizens","bold":true},{"text":"; private firms answer mainly to owners but, through "},{"text":"corporate governance ethics","bold":true},{"text":", must act with "},{"text":"integrity, transparency and accountability to all stakeholders","bold":true},{"text":", beyond mere legal compliance."}]},{"text":[{"text":"In both lists:","bold":true},{"text":" "},{"text":"conflicts of interest","bold":true},{"text":" and "},{"text":"data privacy","bold":true},{"text":". Specific to the public sector: using public office for private gain, absenteeism from public service. Specific to the private sector: price-fixing, fraudulent company accounts, supply-chain exploitation."}]},{"text":[{"text":"Classify the case:","bold":true}]}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"Issue"}]],"rows":[[[{"text":"Works officer demands 10% of a ₦20 million contract in cash"}],[{"text":"Corruption and bribery"}]],[[{"text":"Commissioner approves land to a firm he secretly owns shares in"}],[{"text":"Conflict of interest"}]],[[{"text":"Director promotes his niece over three better-qualified officers"}],[{"text":"Nepotism and favouritism"}]],[[{"text":"Officer intimidates a junior who refused to falsify a report"}],[{"text":"Misuse of power"}]],[[{"text":"Registry staff leak citizens' records on social media"}],[{"text":"Data privacy violation"}]],[[{"text":"Staff sign in at 8 a.m., leave to run private businesses"}],[{"text":"Low integrity/work ethic"}]],[[{"text":"Agency conceals information, files fraudulent reports"}],[{"text":"Lack of accountability and transparency"}]],[[{"text":"Three cement makers agree not to sell below ₦9,500 a bag"}],[{"text":"Anti-competitive behaviour"}]],[[{"text":"Listed company books ₦800 million of fake sales"}],[{"text":"Financial integrity and fraud"}]],[[{"text":"Firm dumps waste in a river and buys from child-labour suppliers"}],[{"text":"Environmental and social responsibility"}]],[[{"text":"Employee passed over because of her religion"}],[{"text":"Harassment and discrimination"}]],[[{"text":"Fintech app leaks customers' card details and BVNs"}],[{"text":"Data privacy and security"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked figure:","bold":true},{"text":" the bribe demanded is 10% of ₦20,000,000 = 0.10 × ₦20,000,000 = "},{"text":"₦2,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Remedy matching:","bold":true},{"text":" relatives being given posts → "},{"text":"merit-based administration","bold":true},{"text":". Whistleblower protection works by "},{"text":"encouraging insiders to report wrongdoing without fear of reprisal","bold":true},{"text":". "},{"text":"Restricting citizens' access to information","bold":true},{"text":" is never a remedy. Taking approved annual leave is not corruption."}]}]}]},{"number":"4.5","title":"Codes of conduct, corruption and accountability in Nigeria","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Code of conduct:","bold":true},{"text":" a written set of rules and standards stating how members of an organisation or public officers must behave (e.g. on gifts, conflicts of interest, asset declaration)."}]},{"text":[{"text":"Corruption:","bold":true},{"text":" the "},{"text":"abuse of entrusted power for private gain","bold":true},{"text":". Forms: "},{"text":"bribery, embezzlement, nepotism, fraud, extortion, abuse of resources","bold":true},{"text":". Types: "},{"text":"petty","bold":true},{"text":" (small, everyday), "},{"text":"grand","bold":true},{"text":" (high-level, large sums), "},{"text":"political","bold":true},{"text":" (manipulating policies or elections)."}]},{"text":[{"text":"Accountability:","bold":true},{"text":" the obligation of leaders and institutions to "},{"text":"explain their actions, accept responsibility","bold":true},{"text":" for decisions, and "},{"text":"face evaluation or consequences","bold":true},{"text":" when performance falls short. Mechanisms: "},{"text":"performance monitoring, legal oversight, public reporting, institutional checks and balances","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Body / law"}],[{"text":"What it does"}]],"rows":[[[{"text":"Code of Conduct for Public Officers","bold":true},{"text":" (Fifth Schedule, 1999 Constitution)"}],[{"text":"Rules for public officers: no conflict of interest, no bribes or improper gifts, asset declaration"}]],[[{"text":"Code of Conduct Bureau (CCB)","bold":true}],[{"text":"Receives and checks public officers' "},{"text":"asset declarations","bold":true},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 19, $study_guide$text":"; refers breaches to the CCT"}]],[[{"text":"Code of Conduct Tribunal (CCT)","bold":true}],[{"text":"Tries breaches of the Code of Conduct"}]],[[{"text":"EFCC","bold":true},{"text":" (Economic and Financial Crimes Commission; Act of 2004, first set up 2002)"}],[{"text":"Investigates and prosecutes "},{"text":"economic and financial crimes","bold":true},{"text":": fraud, money laundering, advance-fee fraud"}]],[[{"text":"ICPC","bold":true},{"text":" (Independent Corrupt Practices and Other Related Offences Commission; Act of 2000)"}],[{"text":"Fights "},{"text":"corruption, especially in the public sector","bold":true},{"text":": bribery, gratification; also prevention and public education"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public officers declare their assets to the CCB on taking office, every four years, and at the end of their term."}]},{"text":[{"text":"Other Nigerian accountability tools: the "},{"text":"Public Procurement Act 2007","bold":true},{"text":" (Bureau of Public Procurement, \"due process\"), the "},{"text":"Freedom of Information Act 2011","bold":true},{"text":", the federal "},{"text":"whistleblower policy (2016)","bold":true},{"text":", and legislative oversight by the National and State Assemblies."}]},{"text":[{"text":"Effects of corruption: "},{"text":"weakens institutions, reduces public trust, limits economic development, undermines fairness and justice","bold":true},{"text":". Leadership response: "},{"text":"strengthen accountability systems, promote transparency, enforce ethical standards","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the "},{"text":"CCB","bold":true},{"text":" handles asset declarations; the "},{"text":"CCT","bold":true},{"text":" is the court that tries breaches. "},{"text":"EFCC","bold":true},{"text":" = financial crimes broadly; "},{"text":"ICPC","bold":true},{"text":" = corrupt practices, mainly public sector."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social contract = give up some rights, accept a central authority, protect other rights; implicit; not the same as government."}]},{"text":[{"text":"Popular in the 16th-18th centuries; explains the origin of government and the obligations of subjects."}]},{"text":[{"text":"Hobbes ("},{"text":"Leviathan","italic":true},{"text":"): brutish state of nature, absolute sovereign. Locke ("},{"text":"Two Treatises","italic":true},{"text":"): life, liberty, property; right to resist."}]},{"text":[{"text":"Rousseau ("},{"text":"The Social Contract","italic":true},{"text":"): general will, \"born free... in chains\". Rawls ("},{"text":"A Theory of Justice","italic":true},{"text":"): veil of ignorance."}]},{"text":[{"text":"Social contract ethics: rules people would accept; fair and acceptable; shared endorsement; mutual trust."}]},{"text":[{"text":"Public sector issues: corruption, conflict of interest, nepotism, misuse of power, poor accountability, data privacy, dilemmas, low work ethic."}]},{"text":[{"text":"Private sector issues come from profit pressure: harassment, conflicts, data, fraud, environment, anti-competitive behaviour."}]},{"text":[{"text":"CCB (assets), CCT (tries breaches), EFCC (financial crimes), ICPC (corrupt practices)."}]}]}],"theory":{"itemId":"cc70d0d1-1eba-599f-9454-cae47c048dda","question":[{"type":"paragraph","text":[{"text":"Compare the social contract theories of Thomas Hobbes and John Locke."}]}]},"practice":[{"topic":"Social Contract and Ethics","named":false}]}},{"kind":"note","itemId":"4e625dcd-6b5f-503a-9773-add218b3cd5f","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Stakeholder and Public Governance","body":"Public governance; stakeholders (meaning, types, shareholders vs stakeholders); Freeman's stakeholder theory and its governance implications; the power/interest grid and the salience model; stakeholder engagement (process, levels, principles, benefits, challenges); crisis (meaning, characteristics, types, stages) and crisis communication management.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"Public governance; stakeholders (meaning, types, shareholders vs stakeholders); Freeman's stakeholder theory and its governance implications; the power/interest grid and the salience model; stakeholder engagement (process, levels, principles, benefits, challenges); crisis (meaning, characteristics, types, stages) and crisis communication management."}],"lessons":[{"number":"5.1","title":"Public governance and stakeholders","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public governance:","bold":true},{"text":" the process by which "},{"text":"public institutions manage resources, implement policies and deliver services to citizens","bold":true},{"text":". Effective public governance depends mainly on "},{"text":"stakeholder participation","bold":true},{"text":"."}]},{"text":[{"text":"Stakeholder:","bold":true},{"text":" any "},{"text":"individual, group or institution that can affect or is affected by","bold":true},{"text":" an organisation's or government's actions, decisions and outcomes. In public governance: those who "},{"text":"gain from public policy or bear its consequences and demand accountability","bold":true},{"text":"."}]},{"text":[{"text":"Examples in public governance:","bold":true},{"text":" citizens, community leaders, traditional rulers, pressure groups, NGOs, labour unions, the press, civil servants, student unions, religious bodies."}]},{"text":[{"text":"Corporate governance:","bold":true},{"text":" the "},{"text":"rules, practices and processes by which a company is directed and controlled","bold":true},{"text":", balancing the interests of its stakeholders."}]}]},{"type":"paragraph","text":[{"text":"Key stakeholders in corporate governance (7):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Shareholders:","bold":true},{"text":" owners who invest capital and expect returns."}]},{$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 20, $study_guide$"text":[{"text":"Board of directors:","bold":true},{"text":" elected by shareholders to "},{"text":"represent their interests and oversee management","bold":true},{"text":"."}]},{"text":[{"text":"Management:","bold":true},{"text":" executives running "},{"text":"day-to-day operations","bold":true},{"text":"."}]},{"text":[{"text":"Employees:","bold":true},{"text":" the workforce carrying out operations."}]},{"text":[{"text":"Customers:","bold":true},{"text":" consumers of the goods or services."}]},{"text":[{"text":"Suppliers and partners:","bold":true},{"text":" provide goods, services or other resources."}]},{"text":[{"text":"Regulators:","bold":true},{"text":" "},{"text":"government bodies that enforce laws and regulations","bold":true},{"text":" on corporate governance."}]}]},{"type":"paragraph","text":[{"text":"Types of stakeholders:","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Examples"}]],"rows":[[[{"text":"Primary","bold":true}],[{"text":"direct, formal stake; essential to survival"}],[{"text":"employees, customers, owners, suppliers"}]],[[{"text":"Secondary","bold":true}],[{"text":"influence or are affected, but no contract or ownership link"}],[{"text":"media, NGOs, pressure groups, community activists"}]],[[{"text":"Internal","bold":true}],[{"text":"inside the organisation"}],[{"text":"employees, managers, owners/board"}]],[[{"text":"External","bold":true}],[{"text":"outside the organisation"}],[{"text":"customers, depositors, suppliers, government, host community"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Every shareholder is a stakeholder, but not every stakeholder is a shareholder.","bold":true},{"text":" Employees, customers and host communities are stakeholders who own no shares."}]},{"text":[{"text":"An environmental NGO in Port Harcourt campaigning against gas flaring with no contract or ownership link is a "},{"text":"secondary","bold":true},{"text":" stakeholder. A bank's "},{"text":"employees","bold":true},{"text":" are internal; the "},{"text":"CBN","bold":true},{"text":", depositors and host community are external."}]},{"text":[{"text":"Firms that sell limestone, bags and diesel to a cement company are its "},{"text":"suppliers and partners","bold":true},{"text":"."}]},{"text":[{"text":"Residents who will live beside a new landfill in Ogun State, bear its smell and health risks and demand explanations are "},{"text":"stakeholders","bold":true},{"text":" (affected by the decision)."}]},{"text":[{"text":"Why public governance looks to the long term:","bold":true},{"text":" public policies shape "},{"text":"intergenerational welfare","bold":true},{"text":" (roads, education, debt affect future generations). It strengthens service delivery by "},{"text":"aligning processes with objectives","bold":true},{"text":"."}]}]}]},{"number":"5.2","title":"Stakeholder theory","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stakeholder theory:","bold":true},{"text":" a management framework holding that organisations, institutions and governments should "},{"text":"not be run for the benefit of one group","bold":true},{"text":" but should recognise and respond to "},{"text":"all groups and individuals who affect or are affected by","bold":true},{"text":" their decisions."}]},{"text":[{"text":"Popularised by "},{"text":"R. Edward Freeman (1984)","bold":true},{"text":" in "},{"text":"Strategic Management: A Stakeholder Approach","italic":true},{"text":". Long-term success depends on the ability to "},{"text":"identify, understand and manage the interests of multiple stakeholders","bold":true},{"text":"."}]},{"text":[{"text":"Shareholder-primacy view","bold":true},{"text":" (associated with Milton Friedman): the main responsibility of business is to "},{"text":"maximise returns to its owners within the law","bold":true},{"text":". Stakeholder theory says managers should "},{"text":"weigh the interests of all affected groups, not only owners' returns","bold":true},{"text":" (it does not say profit should be ignored)."}]}]},{"type":"paragraph","text":[{"text":"Key governance implications of stakeholder theory (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Public interest","bold":true},{"text":" is a central priority."}]},{"text":[{"text":"Inclusiveness","bold":true},{"text":" in decision-making."}]},{"text":[{"text":"Ethical responsibility","bold":true},{"text":" to society."}]},{"text":[{"text":"Accountability and transparency","bold":true},{"text":"."}]},{"text":[{"text":"Sustainable development","bold":true},{"text":" and implementation of policy."}]}]},{"type":"paragraph","text":[{"text":"Three perspectives","bold":true},{"text":" (Donaldson and Preston, 1995):"}]},{"type":"table","header":[[{"text":"Perspective"}],[{"text":"Says"}]],"rows":[[[{"text":"Descriptive","bold":true}],[{"text":"explains how organisations "},{"text":"actually behave","bold":true},{"text":" towards stakeholders, without judging"}]],[[{"text":"Instrumental","bold":true}],[{"text":"attending to stakeholders "},{"text":"helps the firm perform better","bold":true}]],[[{"text":"Normative","bold":true}],[{"text":"firms have a "},{"text":"moral duty","bold":true},{"text":" to consider stakeholders"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Theory vs engagement:","bold":true},{"text":" stakeholder theory supplies the "},{"text":"\"why\"","bold":true},{"text":" (why stakeholders matter); stakeholder engagement is the "},{"text":"\"how\"","bold":true},{"text":" (how they are actually involved)."}]},{"text":[{"text":"\"Concentrating decisions in a small elite\", \"keeping policy information confidential\" or \"profit as the only goal\" are "},{"text":"not","bold":true},{"text":" implications of stakeholder theory."}]},{"text":[{"text":"Stakeholder-based governance enhances accountability by "},{"text":"increasing mutual monitoring","bold":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 21, $study_guide$true},{"text":": many groups watch one another and the government."}]},{"text":[{"text":"Trap: Hobbes, Kelley and Weber are distractors; "},{"text":"Freeman","bold":true},{"text":" is the name, "},{"text":"1984","bold":true},{"text":" the year (1997 belongs to the salience model)."}]}]}]},{"number":"5.3","title":"Stakeholder mapping and salience","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stakeholder mapping:","bold":true},{"text":" identifying stakeholders and "},{"text":"positioning them by attributes such as power and interest","bold":true},{"text":" to plan how to engage each group. The first task in any stakeholder analysis is "},{"text":"identifying all groups that can affect or be affected","bold":true},{"text":"."}]},{"text":[{"text":"Power/interest grid","bold":true},{"text":" (Mendelow): two dimensions, "},{"text":"power","bold":true},{"text":" and "},{"text":"interest","bold":true},{"text":"."}]}]},{"type":"table","header":[[],[{"text":"Low interest"}],[{"text":"High interest"}]],"rows":[[[{"text":"High power","bold":true}],[{"text":"Keep satisfied","bold":true}],[{"text":"Manage closely","bold":true},{"text":" (key players, fully engage)"}]],[[{"text":"Low power","bold":true}],[{"text":"Monitor","bold":true},{"text":" (minimum effort)"}],[{"text":"Keep informed","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Salience model","bold":true},{"text":" ("},{"text":"Mitchell, Agle and Wood, 1997","bold":true},{"text":"): stakeholders are prioritised by "},{"text":"power, legitimacy and urgency","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Power:","bold":true},{"text":" ability to impose its will on the organisation."}]},{"text":[{"text":"Legitimacy:","bold":true},{"text":" the perception that a claim or action is "},{"text":"desirable, proper or appropriate","bold":true},{"text":"."}]},{"text":[{"text":"Urgency:","bold":true},{"text":" the degree to which a claim is "},{"text":"time-sensitive and critical","bold":true},{"text":", calling for "},{"text":"immediate attention","bold":true},{"text":"."}]}]}]}]},{"type":"table","header":[[{"text":"Attributes held"}],[{"text":"Type"}],[{"text":"Class"}]],"rows":[[[{"text":"Power only"}],[{"text":"Dormant","bold":true}],[{"text":"Latent"}]],[[{"text":"Legitimacy only"}],[{"text":"Discretionary","bold":true}],[{"text":"Latent"}]],[[{"text":"Urgency only"}],[{"text":"Demanding","bold":true}],[{"text":"Latent"}]],[[{"text":"Power + legitimacy"}],[{"text":"Dominant","bold":true}],[{"text":"Expectant"}]],[[{"text":"Power + urgency"}],[{"text":"Dangerous","bold":true}],[{"text":"Expectant"}]],[[{"text":"Legitimacy + urgency"}],[{"text":"Dependent","bold":true}],[{"text":"Expectant"}]],[[{"text":"All three"}],[{"text":"Definitive","bold":true}],[{"text":"Most salient"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lagos traders' association worried about a BRT corridor but with little influence (low power, high interest) → "},{"text":"keep informed","bold":true},{"text":"."}]},{"text":[{"text":"A federal ministry that must approve funds but ignores details (high power, low interest) → "},{"text":"keep satisfied","bold":true},{"text":". Risk of neglecting it: it may "},{"text":"become interested and use its power to block","bold":true},{"text":" your plans."}]},{"text":[{"text":"Flood victims in Kogi State with a legitimate, urgent claim but little power → "},{"text":"dependent","bold":true},{"text":". A large union that can strike but has no pending claim (power only) → "},{"text":"dormant","bold":true},{"text":"."}]},{"text":[{"text":"Prioritisation is "},{"text":"not","bold":true},{"text":" by financial contribution, proximity or media visibility."}]},{"text":[{"text":"Memory aid: the three latent types start with "},{"text":"D-D-D","bold":true},{"text":" (dormant, discretionary, demanding); \"dependent\" depends on others' power to act."}]}]}]},{"number":"5.4","title":"Stakeholder engagement","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stakeholder engagement:","bold":true},{"text":" the process by which organisations or government "},{"text":"identify stakeholders, keep communication open, understand their interests and involve them in decisions","bold":true},{"text":", so that policy is implemented successfully. In public governance: involving those who affect or are affected by decisions "},{"text":"in shaping and implementing","bold":true},{"text":" them."}]}]},{"type":"paragraph","text":[{"text":"Process of stakeholder engagement (5 steps, in order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Stakeholder identification","bold":true},{"text":" (list everyone affected)."}]},{"text":[{"text":"Stakeholder analysis","bold":true},{"text":" (study each group's interests, influence, concerns)."}]},{"text":[{"text":"Engagement planning","bold":true},{"text":" (choose the method of engagement)."}]},{"text":[{"text":"Implementation and communication","bold":true},{"text":"."}]},{"text":[{"text":"Monitoring and evaluation","bold":true},{"text":" (final step)."}]}]},{"type":"paragraph","text":[{"text":"Levels of engagement","bold":true},{"text":" (public participation spectrum, least to most public influence):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Inform","bold":true},{"text":" (lowest) 2. "},{"text":"Consult","bold":true},{"text":" 3. "},{"text":"Involve","bold":true},{"text":" 4. "},{"text":"Collaborate","bold":true},{"text":" 5. "},{"text":"Empower","bold":true},{"text":" (final decision in the public's hands)."}]}]},{"type":"paragraph","text":[{"text":"Importance of stakeholder engagement in governance (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Enhances "},{"text":"policy acceptance","bold":true},{"text":"."}]},{"text":[{"text":"Promotes "},{"text":"transparency and accoun$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 22, $study_guide$tability","bold":true},{"text":" (citizens can demand explanations)."}]},{"text":[{"text":"Improves "},{"text":"service delivery","bold":true},{"text":"."}]},{"text":[{"text":"Strengthens "},{"text":"trust and legitimacy","bold":true},{"text":"."}]},{"text":[{"text":"Reduces "},{"text":"conflicts and resistance","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Principles of effective engagement:","bold":true},{"text":" "},{"text":"inclusiveness","bold":true},{"text":", "},{"text":"transparency","bold":true},{"text":", "},{"text":"early and timely","bold":true},{"text":" involvement, "},{"text":"two-way communication","bold":true},{"text":", "},{"text":"respect","bold":true},{"text":", "},{"text":"responsiveness and feedback","bold":true},{"text":", "},{"text":"meaningful","bold":true},{"text":" participation (views can actually change decisions)."}]},{"type":"paragraph","text":[{"text":"Challenges (4):","bold":true},{"text":" "},{"text":"political interference","bold":true},{"text":", "},{"text":"resistance to change","bold":true},{"text":", "},{"text":"poor communication systems","bold":true},{"text":", "},{"text":"low literacy level","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Other benefits","bold":true},{"text":" examiners phrase in their own words: it adds "},{"text":"diverse perspectives","bold":true},{"text":" (adaptability), encourages "},{"text":"collaborative problem-solving","bold":true},{"text":" (innovation), enables "},{"text":"continuous feedback","bold":true},{"text":", "},{"text":"integrates user feedback into service design","bold":true},{"text":", strengthens "},{"text":"transparency norms","bold":true},{"text":" and trust, "},{"text":"broadens participation channels","bold":true},{"text":" (democracy). Open consultation forums mainly strengthen "},{"text":"participation","bold":true},{"text":". It is closely linked to the principle of "},{"text":"transparency","bold":true},{"text":"."}]},{"text":[{"text":"It does "},{"text":"not","bold":true},{"text":" guarantee every stakeholder gets exactly what it wants, does not skip consultation, and does not shift accountability from government to citizens."}]},{"text":[{"text":"Effective engagement needs "},{"text":"inclusive, transparent and meaningful participation of all relevant parties","bold":true},{"text":", not experts only, not telling people after decisions are made."}]},{"text":[{"text":"Poor engagement","bold":true},{"text":" leads to "},{"text":"resistance, low compliance and conflict","bold":true},{"text":" over a policy."}]},{"text":[{"text":"Classify the case:","bold":true}]}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"Answer"}]],"rows":[[[{"text":"Lagos LG chairman shows how a ₦200 million road budget was spent at a town hall"}],[{"text":"Transparency and accountability"}]],[[{"text":"Kaduna team chooses between town halls, Hausa radio jingles, online surveys"}],[{"text":"Engagement planning"}]],[[{"text":"Agency studies each group's interests and influence over a toll policy"}],[{"text":"Stakeholder analysis"}]],[[{"text":"Ogun council publishes a draft budget and collects comments before finalising"}],[{"text":"Consult"}]],[[{"text":"Printed notices to farmers who cannot read them"}],[{"text":"Low literacy level"}]],[[{"text":"Politician invites only his supporters to consultations"}],[{"text":"Political interference"}]],[[{"text":"Ibadan motor park talks with union leaders only, leaving out traders, commuters, persons with disabilities"}],[{"text":"Inclusiveness breached"}]]]}]},{"number":"5.5","title":"Crisis: meaning, characteristics, types and stages","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Crisis:","bold":true},{"text":" a "},{"text":"sudden, unexpected event","bold":true},{"text":" threatening an organisation's operations, reputation, stakeholders or the sustainability of a decision, forcing decisions under "},{"text":"time pressure and uncertainty","bold":true},{"text":". Marks: "},{"text":"public panic, violent protests, destruction of property, loss of lives","bold":true},{"text":"."}]},{"text":[{"text":"Characteristics:","bold":true},{"text":" serious "},{"text":"threat","bold":true},{"text":", "},{"text":"surprise","bold":true},{"text":", "},{"text":"uncertainty","bold":true},{"text":", "},{"text":"little time","bold":true},{"text":" for decisions. A crisis is "},{"text":"not","bold":true},{"text":" routine or fully predictable."}]},{"text":[{"text":"Types of crisis:","bold":true},{"text":" natural disasters (floods); technological (system failures, explosions); confrontation (protests, boycotts, strikes); malevolence (terrorism, kidnapping, product tampering, cyber attacks); organisational misdeeds (fraud, deception, management misconduct); workplace violence; rumours and misinformation; financial/economic crises; health crises (epidemics)."}]}]},{"type":"paragraph","text":[{"text":"Steps of crisis management (3, in order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Getting prepared for crisis","bold":true},{"text":" (pre-crisis: prevention and preparedness). This is the "},{"text":"first","bold":true},{"text":" stage."}]},{"text":[{"text":"Quick response and communication","bold":true},{"text":" (crisis/response stage)."}]},{"text":[{"text":"Recovery strategy","bold":true},{"text":" (post-crisis: recovery, evaluation, learning)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pre-crisis activities:","bold":true},{"text":" scanning for early warning signs, preparing a crisis communication plan, training spokespersons, drafting pre-approved message templates."}]},{"text":[{"text":"Response:","bold":true},{"text":" within an hour of a tanker explosion at an Onitsha market, the government issues a statement, opens a hotline and sends fire and medical teams → "},{"text":"quick response and communication","bold":tru$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 23, $study_guide$e},{"text":". Issuing a holding statement belongs here."}]},{"text":[{"text":"Post-crisis:","bold":true},{"text":" months after a market fire in Ibadan, stalls are rebuilt and traders get soft loans → "},{"text":"recovery strategy","bold":true},{"text":". Evaluating how the crisis was handled and updating the plan, and rebuilding reputation, are post-crisis."}]},{"text":[{"text":"Other models: "},{"text":"Fink's four stages:","bold":true},{"text":" prodromal (warning), acute, chronic, resolution. "},{"text":"Mitroff's five phases:","bold":true},{"text":" signal detection, probing and prevention, damage containment, recovery, learning."}]},{"text":[{"text":"Crisis management plan contains:","bold":true},{"text":" crisis team members and roles, up-to-date contacts for stakeholders and media, pre-approved templates and procedures. Never \"a promise that the organisation will never face a crisis\"."}]},{"text":[{"text":"Crisis team:","bold":true},{"text":" senior decision-makers, a communications lead, legal advice and heads of affected operations."}]}]}]},{"number":"5.6","title":"Crisis communication management","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Crisis communication:","bold":true},{"text":" the "},{"text":"collection, processing and sharing of information","bold":true},{"text":" needed to deal with a crisis, with affected stakeholders and the public."}]},{"text":[{"text":"Why it is a governance priority:","bold":true},{"text":" "},{"text":"unmanaged information gaps intensify public uncertainty and distrust","bold":true},{"text":"; "},{"text":"timely, accurate and empathetic","bold":true},{"text":" communication maintains public trust and enables effective response."}]},{"text":[{"text":"Holding statement:","bold":true},{"text":" a short statement issued "},{"text":"very quickly","bold":true},{"text":" that acknowledges the incident, expresses concern and promises updates before all facts are known."}]}]},{"type":"paragraph","text":[{"text":"Principles of crisis communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Communicate "},{"text":"early","bold":true},{"text":" (say what is known so far)."}]},{"text":[{"text":"Be "},{"text":"accurate","bold":true},{"text":" and "},{"text":"honest","bold":true},{"text":"."}]},{"text":[{"text":"Be "},{"text":"consistent","bold":true},{"text":": "},{"text":"one designated spokesperson","bold":true},{"text":", coordinated verified messages."}]},{"text":[{"text":"Show "},{"text":"empathy","bold":true},{"text":" for those affected."}]},{"text":[{"text":"Use "},{"text":"two-way communication","bold":true},{"text":" (hotlines, feedback)."}]},{"text":[{"text":"Inform employees early","bold":true},{"text":"."}]},{"text":[{"text":"Monitor social media","bold":true},{"text":" and correct false claims quickly through official channels."}]}]},{"type":"paragraph","text":[{"text":"Response strategies","bold":true},{"text":" (Coombs' situational crisis communication theory):"}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Strategies"}]],"rows":[[[{"text":"Deny"}],[{"text":"attack the accuser, denial, "},{"text":"scapegoating","bold":true},{"text":" (blaming an outside party)"}]],[[{"text":"Diminish"}],[{"text":"excuse, justification"}]],[[{"text":"Rebuild"}],[{"text":"compensation, "},{"text":"apology","bold":true}]],[[{"text":"Bolster"}],[{"text":"reminding of past good works, ingratiation, victimage"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Poor communication","bold":true},{"text":" in a security crisis leads to "},{"text":"public panic, spread of misinformation and erosion of institutional credibility","bold":true},{"text":"."}]},{"text":[{"text":"Bad practice:","bold":true},{"text":" \"no comment\", silence until attention fades, denying the crisis, letting agencies release different messages, waiting until every fact is confirmed, attacking those who reported it."}]},{"text":[{"text":"At fault for a preventable crisis:","bold":true},{"text":" "},{"text":"accept responsibility, apologise and take corrective action","bold":true},{"text":" to protect long-term trust."}]},{"text":[{"text":"Three Bauchi officials give three death tolls for a cholera outbreak → needed "},{"text":"a single spokesperson and coordinated, verified messages","bold":true},{"text":"."}]},{"text":[{"text":"Contaminated yoghurt batch in Lagos → "},{"text":"promptly recall and tell the public honestly","bold":true},{"text":" what is known, what is being done and how to get refunds."}]},{"text":[{"text":"False WhatsApp claims that Abuja filling stations will shut → "},{"text":"monitor social media and correct quickly","bold":true},{"text":" with verified information. A toll-free outbreak hotline shows "},{"text":"two-way communication","bold":true},{"text":"."}]},{"text":[{"text":"Employees should hear first because they act as "},{"text":"informal spokespersons","bold":true},{"text":"; learning facts from the media damages morale."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public governance = public institutions managing resources, implementing policy, delivering services; depends on stakeholder participation."}]},{"text":[{"text":"Stakeholder = can affect or is affected; every shareholder is a stakeholder, not the reverse."}]},{"text":[{"text":"Freeman (1984): stakeholder theory is the \"why\"; engagement is the \"how\"."}]},{"text":[{"text":"Grid: manage closely, keep satisfied, keep informed, monitor."}]},{"text":[{"text":"Salience (Mitchell, Agle and Wood, 1997): power, legitimacy, urgency; all three = definitive."}]},{"text":[{"text":"Engagement: identification, analysis, planning, implementation and communication, monitoring and evaluation."}]},{"text":[{"text":"Levels: inform, consult, involve, collaborate, empower. Challenges: politics, resistance, poor communication, low literacy."}]},{"text":[{"text":"Crisis steps: prepare, r$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 24, $study_guide$espond and communicate, recover. Communicate early, accurately, consistently, with empathy."}]}]}],"theory":{"itemId":"331009dd-0fe4-56cb-8814-e3b4bee7f661","question":[{"type":"paragraph","text":[{"text":"Classify each stakeholder using the salience model: (a) a regulator with power and a legitimate but not urgent claim; (b) protesters blocking a road with an urgent but illegitimate claim and power to disrupt; (c) a charity with a legitimate claim only."}]}]},"practice":[{"topic":"Stakeholder and Public Governance","named":false}]}},{"kind":"note","itemId":"8d255a72-1b9c-5d89-ba08-d3cc9f3d578e","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Governance in the Public Services","body":"What governance and corporate governance mean; the Four P's and the four principles; the eight characteristics of good governance; the public sector, its three Es and how public governance differs from private; why good public governance matters; accountability; and the hindrances to good governance in Nigeria.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What governance and corporate governance mean; the Four P's and the four principles; the eight characteristics of good governance; the public sector, its three Es and how public governance differs from private; why good public governance matters; accountability; and the hindrances to good governance in Nigeria."}],"lessons":[{"number":"6.1","title":"Governance, corporate governance and the Four P's","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Origin:","bold":true},{"text":" \"governance\" comes from the Greek verb "},{"text":"kubernaein","bold":true},{"text":" (kubernao), meaning "},{"text":"to steer","bold":true},{"text":". Governance is not new; it is as old as human civilisation."}]},{"text":[{"text":"Governance (simple):","bold":true},{"text":" the process of decision-making "},{"text":"and","bold":true},{"text":" the process by which decisions are implemented (or not implemented). Also: the system by which a firm is controlled and operates, and the mechanisms that hold the company and its people accountable."}]},{"text":[{"text":"Fuller meaning:","bold":true},{"text":" the whole framework of processes, functions, structures, rules, laws and norms arising from relationships, power and communication; it manages, allocates and mobilises resources to address collective needs."}]},{"text":[{"text":"5 contexts:","bold":true},{"text":" corporate, institutional, national, local, international governance. (Levels also named: public, global, non-profit, corporate and project governance.)"}]},{"text":[{"text":"Corporate governance:","bold":true},{"text":" the structures, processes, cultures and systems that make business organisations operate successfully; the rules, practices and processes by which a company is "},{"text":"directed and controlled","bold":true},{"text":" to balance the interests of its stakeholders."}]},{"text":[{"text":"Stakeholders in corporate governance:","bold":true},{"text":" shareholders, board of directors (elected by shareholders to oversee management), management, employees, customers, suppliers and partners, regulators."}]},{"text":[{"text":"Four P's of governance:","bold":true},{"text":" "},{"text":"Purpose, People, Process, Performance","bold":true},{"text":". Profit is "},{"text":"not","bold":true},{"text":" one."}]}]},{"type":"paragraph","text":[{"text":"Four principles of good corporate governance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Accountability:","bold":true},{"text":" the board answers to shareholders and other stakeholders."}]},{"text":[{"text":"Transparency:","bold":true},{"text":" timely and proper disclosure on all material matters, including financial situation, performance and ownership."}]},{"text":[{"text":"Fairness:","bold":true},{"text":" all shareholders, including minority and foreign shareholders, get fair treatment."}]},{"text":[{"text":"Responsibility:","bold":true},{"text":" the organisation complies with laws and regulations and considers the interests of all stakeholders."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Good governance is "},{"text":"not","bold":true},{"text":" about ticking boxes or adding layers of bureaucracy; it promotes an environment that drives growth, resilience and long-term success."}]},{"text":[{"text":"What fuelled the corporate governance debate:","bold":true},{"text":" fraud, corruption, opportunistic business leaders, agency problems, bankruptcies, internationalisation, deregulation and integration of financial markets, complex financial instruments and their risks, changing social expectations, inadequate reporting and failing auditors, and excessive directors' remuneration. Rising literacy is "},{"text":"not","bold":true},{"text":" one of them."}]},{"text":[{"text":"Traps: \"fair treatment of minority shareholders\" is "},{"text":"fairness","bold":true},{"text":", not responsibility; \"complying with laws and considering all stakeholders\" is "},{"text":"responsibility","bold":true},{"text":"; \"disclosure of financial results and ownership\" is "},{"text":"transparency","bold":true},{"text":"."}]}]}]},{"number":"6.2","title":"The eight characteristics of good governance","mustKnow":[{"type":"paragraph","text":[{"text":"Good (effective) governance has "},{"text":"8","bold":true},{"text":" major characteristics:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Participation:","bold":true},{"text":" by both men and women, either "},{"text":"directly","bold":true},{"text":" or through legitimate intermediate institutions or representatives."}]},{"text":[{"text":"Rule of law:","bold":true},{"text":" fair legal frameworks "},{"text":"enforced impartially","bold":true},{"text":", with full protection of human rights, particularly those of "},{"text":"minorities","bold":true},{"text":". All individuals and institutions are subject $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 25, $study_guide$to laws that are publicly known, fairly enforced and independently adjudicated."}]},{"text":[{"text":"Transparency:","bold":true},{"text":" decisions and their enforcement "},{"text":"follow rules and regulations","bold":true},{"text":", and information is "},{"text":"freely available and directly accessible","bold":true},{"text":" to those affected."}]},{"text":[{"text":"Responsiveness:","bold":true},{"text":" institutions and processes try to serve "},{"text":"all stakeholders within a reasonable timeframe","bold":true},{"text":"."}]},{"text":[{"text":"Consensus oriented:","bold":true},{"text":" "},{"text":"mediation","bold":true},{"text":" of the diverse interests in society to reach a "},{"text":"broad consensus","bold":true},{"text":" on what is best for the whole community, with a broad, long-term perspective."}]},{"text":[{"text":"Equity and inclusiveness:","bold":true},{"text":" all members feel they have a "},{"text":"stake","bold":true},{"text":" and are not excluded; all groups, "},{"text":"especially the most vulnerable","bold":true},{"text":", have opportunities to take part and improve or maintain their well-being."}]},{"text":[{"text":"Effectiveness and efficiency:","bold":true},{"text":" procedures and institutions produce "},{"text":"results that meet the needs of society","bold":true},{"text":" while making the "},{"text":"best use of resources","bold":true},{"text":"."}]},{"text":[{"text":"Accountability:","bold":true},{"text":" institutions answer to the public and their stakeholders. Accountability can only be enforced with "},{"text":"transparency and the rule of law","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Not characteristics: centralisation, exclusion of minorities, nepotism, secrecy, restriction of civil liberties."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A federal agency takes three years on a pension claim that rules say must be decided in 90 days: "},{"text":"responsiveness","bold":true},{"text":" is lacking."}]},{"text":[{"text":"The Federal Government spends months negotiating the minimum wage with labour unions, employers and state governments until a broadly acceptable figure emerges: "},{"text":"consensus orientation","bold":true},{"text":"."}]},{"text":[{"text":"Student bodies such as the BSA and MSA giving members a say are examples of "},{"text":"participation","bold":true},{"text":"."}]},{"text":[{"text":"Related ideas you will meet in questions:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legitimacy","bold":true},{"text":" rises when procedures are seen as "},{"text":"fair","bold":true},{"text":"."}]},{"text":[{"text":"Transparency mechanisms involve "},{"text":"public","bold":true},{"text":" access to records; transparency helps prevent misuse of "},{"text":"public authority","bold":true},{"text":"."}]},{"text":[{"text":"Clear "},{"text":"service standards","bold":true},{"text":" improve "},{"text":"predictability","bold":true},{"text":"; predictability and fairness build "},{"text":"public trust","bold":true},{"text":"."}]},{"text":[{"text":"Policy coherence","bold":true},{"text":" means government actions are "},{"text":"aligned and mutually reinforcing","bold":true},{"text":" across sectors."}]},{"text":[{"text":"Regulatory governance","bold":true},{"text":" ensures rules are "},{"text":"fairly implemented","bold":true},{"text":", not selectively applied."}]},{"text":[{"text":"Professionalism","bold":true},{"text":" means adherence to "},{"text":"established","bold":true},{"text":" standards."}]},{"text":[{"text":"Balancing today's service delivery with future sustainability shows "},{"text":"strategic vision","bold":true},{"text":"."}]}]}]}]}]},{"number":"6.3","title":"The public sector, the three Es and public vs private governance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public sector:","bold":true},{"text":" government organisations and agencies responsible for delivering "},{"text":"public goods and services","bold":true},{"text":" (ministries, public schools, health facilities, law enforcement)."}]},{"text":[{"text":"Private sector:","bold":true},{"text":" businesses owned and controlled by individuals or entities outside government; profit-oriented (SMEs, corporations, start-ups, family businesses, partnerships)."}]},{"text":[{"text":"Three Es","bold":true},{"text":" (general objectives of public sector organisations):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Economy:","bold":true},{"text":" value for money; delivering on budget, on time, within resource limits."}]},{"text":[{"text":"Efficiency:","bold":true},{"text":" acceptable return on resources. "},{"text":"Efficiency = work output ÷ work inputs.","bold":true}]},{"text":[{"text":"Effectiveness:","bold":true},{"text":" the extent to which the organisation delivers what it is intended to deliver."}]}]}]}]},{"type":"table","header":[[{"text":"Basis"}],[{"text":"Public sector enterprise"}],[{"text":"Private sector enterprise"}]],"rows":[[[{"text":"Ownership (the "},{"text":"major","bold":true},{"text":" difference)"}],[{"text":"Owned and operated by government"}],[{"text":"Owned by individuals or shareholders"}]],[[{"text":"Objective"}],[{"text":"Public needs, general welfare"}],[{"text":"Maximise profit and shareholder value"}]],[[{"text":"Decision-making"}],[{"text":"Bureaucratic, several levels of approval"}],[{"text":"Flexible, responds quickly"}]],[[{"text":"Accountable to"}],[{"text":"Government and the public"}],[{"text":"Mainly shareholders"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Public sector governance:","bold":true},{"text":" ensures public sector entities meet their objectives and intended outcomes for citizens and operate ethically, transparently, efficiently and effectively. They are accountable to their "},{"text":"ultimate owners, the citizens","bold":true},{"text":"."}]},{"text":[{"text":"Ob$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 26, $study_guide$jective:","bold":true},{"text":" to "},{"text":"serve the public interest, provide essential services and ensure national stability and well-being","bold":true},{"text":"."}]},{"text":[{"text":"Nigeria:","bold":true},{"text":" citizens' oversight is exercised through the "},{"text":"National and State Assemblies","bold":true},{"text":" and, at local level, "},{"text":"councillors","bold":true},{"text":". Policy guideline example: the "},{"text":"Corporate Governance Manual for Governing Boards/Councils of Federal Parastatals, Agencies and Commissions","bold":true},{"text":"."}]},{"text":[{"text":"Public governance differs from private mainly by its emphasis on "},{"text":"public interest, equity, accountability and democratic participation","bold":true},{"text":". Transparency rules are "},{"text":"stricter","bold":true},{"text":" in public governance because it uses "},{"text":"public resources and authority","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (₦):","bold":true},{"text":" a state licensing office has a budget of ₦32,000,000, spends ₦30,000,000 on time, and issues 12,000 licences against a target of 15,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Economy: spent ₦30,000,000 of ₦32,000,000, on time, so it was economical."}]},{"text":[{"text":"Efficiency: cost per licence = ₦30,000,000 ÷ 12,000 = "},{"text":"₦2,500","bold":true},{"text":"; or 12,000 ÷ 30 = "},{"text":"400 licences per ₦1 million","bold":true},{"text":"."}]},{"text":[{"text":"Effectiveness: 12,000 ÷ 15,000 × 100 = "},{"text":"80%","bold":true},{"text":" of the intended output."}]}]}]},{"text":[{"text":"A health board builds every clinic on time and within budget, but child deaths do not fall because there are no trained staff: "},{"text":"economy","bold":true},{"text":" is fine, "},{"text":"effectiveness","bold":true},{"text":" is lacking."}]},{"text":[{"text":"Challenges in public (listed) company governance (4):","bold":true},{"text":" managing diverse shareholder interests; pressure for short-term results versus long-term strategy; regulatory scrutiny and compliance burdens; transparency and disclosure requirements."}]},{"text":[{"text":"Agency relationship:","bold":true},{"text":" managers do not own the business but run it for the owners (principals) and owe them a "},{"text":"fiduciary duty","bold":true},{"text":"."}]},{"text":[{"text":"Challenges in private company governance (4):","bold":true},{"text":" lack of transparency and public accountability; succession planning and family-business dynamics; limited access to capital markets; balancing growth with control. Managing a large, diverse shareholder base is a "},{"text":"public","bold":true},{"text":" company problem."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"An Onitsha family firm whose children quarrel over who takes over: "},{"text":"succession planning","bold":true},{"text":"."}]},{"text":[{"text":"A Lagos tech start-up fearing outside investors will dilute the founders' say: "},{"text":"balancing growth with control","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Other differences:","bold":true},{"text":" public company boards are "},{"text":"larger","bold":true},{"text":", mix executive and non-executive directors and stress "},{"text":"independence","bold":true},{"text":"; private boards are smaller and close to the owners. Listed companies face heavy disclosure (financial performance, executive pay, material events) and tend to be more "},{"text":"risk-averse","bold":true},{"text":" because of regulator and public scrutiny. Public companies often focus on shareholder value; private ones have more room for a stakeholder approach. Both face growing pressure on CSR."}]},{"text":[{"text":"Public governance also needs mechanisms to manage "},{"text":"uncertainty and risk","bold":true},{"text":", procedures to resolve "},{"text":"administrative conflicts","bold":true},{"text":", and must balance "},{"text":"efficiency with equity","bold":true},{"text":"."}]}]}]},{"number":"6.4","title":"Importance of good public governance and accountability","mustKnow":[{"type":"paragraph","text":[{"text":"Importance of good public sector governance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Central to the effective operation of all organisations, stakeholders and government."}]},{"text":[{"text":"Encourages "},{"text":"global investors","bold":true},{"text":" to invest in the economy."}]},{"text":[{"text":"Improves the efficiency and effectiveness of organisations."}]},{"text":[{"text":"Sets clear standards for management practice and decision-making, giving better services and outcomes."}]},{"text":[{"text":"Promotes transparency, accountability and responsible decisions, raising "},{"text":"public trust and confidence","bold":true},{"text":" in government institutions."}]},{"text":[{"text":"Assures citizens that their welfare is the government's primary concern and that the public service will be run efficiently and effectively."}]},{"text":[{"text":"Creates an enabling environment where citizens "},{"text":"voluntarily participate","bold":true},{"text":" in governance and contribute to national development."}]},{"text":[{"text":"Encourages innovation and creativity."}]},{"text":[{"text":"Assures stakeholders that those who "},{"text":"mismanage or abuse trust will be sanctioned","bold":true},{"text":" under the law."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Main reason it matters: it ensures the "},{"text":"efficient, transparent and accountable delivery of services that meet citizens' needs","bold":true},{"text":". It promotes "},{"text":"fairness and equity","bold":true},{"text":" in allocating public resources and reduces "},{"text":"corruption and misuse of power","bold":true},{"text":"."}]},{"text":[{"text":"Accountability:","bold":true},{"text":" the obligation o$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 27, $study_guide$f leaders and institutions to "},{"text":"explain their actions, accept responsibility for decisions and face consequences","bold":true},{"text":" when performance falls short; officials must answer to the public and oversight bodies."}]},{"text":[{"text":"4 accountability mechanisms:","bold":true},{"text":" performance monitoring, legal oversight, public reporting, institutional checks and balances."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Good governance does "},{"text":"not","bold":true},{"text":" remove the need for laws, protect government from criticism or raise civil servants' pay."}]},{"text":[{"text":"Accountability deters misconduct by raising the likelihood of "},{"text":"detection","bold":true},{"text":". Executive immunity from all review is "},{"text":"not","bold":true},{"text":" an accountability mechanism."}]}]}]},{"number":"6.5","title":"Hindrances to good governance in the public services (Nigeria)","mustKnow":[{"type":"paragraph","text":[{"text":"5 leadership challenges (hindrances) in governance:","bold":true}]},{"type":"table","header":[[{"text":"Hindrance"}],[{"text":"Meaning"}],[{"text":"Effects"}],[{"text":"Leadership response"}]],"rows":[[[{"text":"Corruption and misuse of power"}],[{"text":"Using authority for personal gain (bribery, embezzlement, nepotism, abuse of resources)"}],[{"text":"Weakens institutions, cuts trust, limits development, undermines justice"}],[{"text":"Strengthen accountability, promote transparency, enforce ethics"}]],[[{"text":"Lack of transparency"}],[{"text":"Opaque decisions, no access to information"}],[{"text":"Suspicion, low participation, room for corruption"}],[{"text":"Open communication, public reporting, inclusive policy talks"}]],[[{"text":"Weak institutions"}],[{"text":"Lacking structure, capacity or independence to enforce laws"}],[{"text":"Poor service delivery, poor enforcement, reliance on informal networks"}],[{"text":"Institutional reform, capacity building, stronger governance frameworks"}]],[[{"text":"Political interference"}],[{"text":"Outsiders steer decisions for personal or partisan gain"}],[{"text":"Less autonomy, policy inconsistency, lower standards"}],[{"text":"Professional ethics, institutional safeguards, merit-based decisions"}]],[[{"text":"Low citizen trust"}],[{"text":"Citizens lose confidence and disengage"}],[{"text":"Resistance to policy, civic withdrawal"}],[{"text":"Show integrity, deliver tangible results"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Low citizen trust is caused by corruption scandals, poor service delivery and lack of accountability."}]},{"text":[{"text":"Weak governance results from (4):","bold":true},{"text":" passive followership, civic apathy, lack of accountability mechanisms, weak institutional structures."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A board overruled by politicians who demand jobs and contracts for party loyalists is "},{"text":"political interference","bold":true},{"text":"."}]},{"text":[{"text":"The major hindrance in African public services is "},{"text":"systemic corruption, weak institutions and lack of accountability mechanisms","bold":true},{"text":". An independent judiciary, a free press, decentralisation and merit-based recruitment "},{"text":"support","bold":true},{"text":" good governance; they are not hindrances."}]},{"text":[{"text":"Low voter turnout","bold":true},{"text":" (for example, under one in four registered voters) reduces leadership "},{"text":"accountability and the legitimacy","bold":true},{"text":" of governance; it does not show satisfaction."}]},{"text":[{"text":"Other Nigerian public-service problems you should recognise: nepotism and favouritism in hiring, conflict of interest, absenteeism and low work ethic, poor record-keeping and limited access to information."}]},{"text":[{"text":"Active","bold":true},{"text":" followership strengthens governance; only "},{"text":"passive","bold":true},{"text":" followership weakens it."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Governance comes from Greek kubernaein, \"to steer\": deciding and implementing decisions."}]},{"text":[{"text":"Four P's: Purpose, People, Process, Performance. Four principles: accountability, transparency, fairness, responsibility."}]},{"text":[{"text":"Eight characteristics: participation, rule of law, transparency, responsiveness, consensus oriented, equity and inclusiveness, effectiveness and efficiency, accountability."}]},{"text":[{"text":"Accountability needs transparency and the rule of law."}]},{"text":[{"text":"Three Es: economy (value for money), efficiency (output ÷ input), effectiveness (delivers what was intended)."}]},{"text":[{"text":"Public vs private: ownership is the major difference; public answers to government and citizens."}]},{"text":[{"text":"Nigeria: oversight by National and State Assemblies and councillors."}]},{"text":[{"text":"Five hindrances: corruption, lack of transparency, weak institutions, political interference, low citizen trust."}]}]}],"theory":{"itemId":"9a2aebc6-8335-563c-ae90-7061517369a9","question":[{"type":"paragraph","text":[{"text":"A federal agency budgeted ₦50,000,000 to process 20,000 passport applications. It spent ₦48,000,000 and processed 16,000. Compute its cost per application and the share of its target achieved, and say which of the three Es each figure measures."}]}]},"practice":[{"topic":"Governance in the Public Services","named":false}]}},{"kind":"note","itemId":"239a1e62-2598-5173-9174-ff48406920a0","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Open Government Partnerships","body":"What the Open Government Partnership (OGP) is, when and where it began and its eight founders; its aims, core values and the Open Government Declaration; how it is run; how a country qualifies and joins; national action plans; benefits and challenges; and Nigeria's journey in OGP.","noteT$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 28, $study_guide$ype":"guide_topic","number":7,"mustKnow":[{"text":"What the Open Government Partnership (OGP) is, when and where it began and its eight founders; its aims, core values and the Open Government Declaration; how it is run; how a country qualifies and joins; national action plans; benefits and challenges; and Nigeria's journey in OGP."}],"lessons":[{"number":"7.1","title":"What OGP is and how it began","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Open Government Partnership (OGP):","bold":true},{"text":" a "},{"text":"voluntary","bold":true},{"text":" partnership of "},{"text":"governments and civil society","bold":true},{"text":" that secures "},{"text":"concrete commitments","bold":true},{"text":" from governments to make governance more "},{"text":"open, accountable and responsive","bold":true},{"text":" to citizens. It is not a UN treaty, an African Union agency or a company, and it imposes no sanctions or loans."}]},{"text":[{"text":"Open government:","bold":true},{"text":" a government whose activities and information are open to citizens, who can take part in decisions and hold it to account."}]},{"text":[{"text":"Launched:","bold":true},{"text":" "},{"text":"20 September 2011","bold":true},{"text":", on the sidelines of the "},{"text":"United Nations General Assembly in New York","bold":true},{"text":"."}]},{"text":[{"text":"8 founding governments:","bold":true},{"text":" "},{"text":"Brazil, Indonesia, Mexico, Norway, the Philippines, South Africa, the United Kingdom, the United States","bold":true},{"text":". The only African founder is "},{"text":"South Africa","bold":true},{"text":". Nigeria was "},{"text":"not","bold":true},{"text":" a founder."}]},{"text":[{"text":"Memory hook: \""},{"text":"B","bold":true},{"text":"ig "},{"text":"I","bold":true},{"text":"deas "},{"text":"M","bold":true},{"text":"ake "},{"text":"N","bold":true},{"text":"ations "},{"text":"P","bold":true},{"text":"rogress: "},{"text":"S","bold":true},{"text":"outh "},{"text":"A","bold":true},{"text":"frica, "},{"text":"U","bold":true},{"text":"K, "},{"text":"U","bold":true},{"text":"S.\""}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"OGP brings governments and civil society organisations (CSOs) to the same table as "},{"text":"equal partners","bold":true},{"text":"; this is its distinctive feature."}]},{"text":[{"text":"It has grown from 8 founders to a membership of dozens of countries plus a "},{"text":"local programme","bold":true},{"text":" for states, provinces and cities (subnational governments)."}]},{"text":[{"text":"Trap: 2011 is the launch year; "},{"text":"2016","bold":true},{"text":" is the year Nigeria joined."}]}]}]},{"number":"7.2","title":"Aims, core values and the Open Government Declaration","mustKnow":[{"type":"paragraph","text":[{"text":"Core aim:","bold":true},{"text":" to secure concrete commitments from governments to "},{"text":"promote transparency, empower citizens, fight corruption and harness new technologies","bold":true},{"text":" to strengthen governance."}]},{"type":"paragraph","text":[{"text":"4 core values (principles) of OGP:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Transparency:","bold":true},{"text":" government information is open, complete, timely and freely available."}]},{"text":[{"text":"Civic (citizen) participation:","bold":true},{"text":" citizens take part in debate and decisions and contribute ideas."}]},{"text":[{"text":"Public accountability:","bold":true},{"text":" rules and mechanisms that make officials justify their actions and accept consequences."}]},{"text":[{"text":"Technology and innovation","bold":true},{"text":" for openness and accountability."}]}]},{"type":"paragraph","text":[{"text":"Open Government Declaration:","bold":true},{"text":" the document every participating government must "},{"text":"endorse","bold":true},{"text":". Its "},{"text":"4 commitments:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Increase the "},{"text":"availability of information","bold":true},{"text":" about government activities."}]},{"text":[{"text":"Support "},{"text":"civic participation","bold":true},{"text":"."}]},{"text":[{"text":"Implement the "},{"text":"highest standards of professional integrity","bold":true},{"text":" throughout government (aimed at "},{"text":"fighting corruption","bold":true},{"text":")."}]},{"text":[{"text":"Increase "},{"text":"access to new technologies","bold":true},{"text":" for openness and accountability."}]}]},{"type":"paragraph","text":[{"text":"Restricting civil society is "},{"text":"not","bold":true},{"text":" a commitment."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Technology","bold":true},{"text":" is central because it "},{"text":"facilitates transparency, citizen participation and service delivery innovation","bold":true},{"text":". It is not for surveillance, replacing civil servants or centralising all communication."}]},{"text":[{"text":"Open government data","bold":true},{"text":" aims to make government datasets "},{"text":"publicly accessible","bold":true},{"text":" to promote "},{"text":"innovation, accountability and civic engagement","bold":true},{"text":", not to sell or hide data."}]},{"text":[{"text":"Meaningful participation must be supported by "},{"text":"access to relevant information","bold":true},{"text":"; without information, consultation is only symbolic."}]},{"text":[{"text":"Phrases to recognise:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"OGP supports "},{"text":"value-driven governance","bold":true},{"text":" (reforms aligned with public values)."}]},{"text":[{"text":"It links openness to better "},{"text":"developmental","bold":true},{"text":" outcomes for society."}]},{"text":[{"text":"It uses transparency to build "},{"text":"trust","bold":true},{"text":" and enhance "},{"text":"administrative efficiency",$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 29, $study_guide$"bold":true},{"text":"."}]},{"text":[{"text":"It improves policy quality by "},{"text":"incorporating diverse inputs","bold":true},{"text":"."}]},{"text":[{"text":"It strengthens "},{"text":"administrative accountability","bold":true},{"text":", letting citizens challenge administrative decisions."}]},{"text":[{"text":"It promotes "},{"text":"comparative accountability","bold":true},{"text":": governments benchmark progress against peers."}]},{"text":[{"text":"It treats "},{"text":"learning from failure","bold":true},{"text":" as a way to "},{"text":"improve future reforms","bold":true},{"text":"."}]},{"text":[{"text":"It normalises "},{"text":"transparent decision-making","bold":true},{"text":", reducing public suspicion."}]},{"text":[{"text":"It encourages "},{"text":"publishing performance indicators","bold":true},{"text":" for public services, "},{"text":"regulatory transparency","bold":true},{"text":" in enforcement, and "},{"text":"partnership transparency","bold":true},{"text":" in public-private partnerships."}]}]}]},{"text":[{"text":"A state publishes its full budget and monthly spending online and CSOs use the data to question a road contract: OGP's aim of "},{"text":"using transparency to empower citizens to hold government accountable","bold":true},{"text":"."}]}]}]},{"number":"7.3","title":"How OGP is run","mustKnow":[{"type":"table","header":[[{"text":"Body"}],[{"text":"What it does"}]],"rows":[[[{"text":"Steering Committee","bold":true}],[{"text":"Executive body; "},{"text":"equal numbers of government and civil society","bold":true},{"text":" representatives"}]],[[{"text":"Co-chairs","bold":true}],[{"text":"Leadership rotates "},{"text":"every year","bold":true},{"text":" between "},{"text":"one government co-chair and one civil society co-chair","bold":true}]],[[{"text":"Support Unit","bold":true}],[{"text":"Small "},{"text":"permanent secretariat","bold":true},{"text":": institutional memory, communications, partner relationships; a neutral party between governments and CSOs"}]],[[{"text":"Independent Reporting Mechanism (IRM)","bold":true}],[{"text":"Independent reports assessing how each member "},{"text":"develops and implements","bold":true},{"text":" its action plan"}]],[[{"text":"International Experts Panel (IEP)","bold":true}],[{"text":"Oversees the IRM","bold":true},{"text":" and the quality of its reports"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The IRM matters for "},{"text":"credibility","bold":true},{"text":": it gives an "},{"text":"independent check","bold":true},{"text":" on whether governments actually deliver what they promise. Governments do not grade themselves."}]},{"text":[{"text":"Equal representation on the Steering Committee mirrors OGP's principle that government and civil society are partners."}]}]}]},{"number":"7.4","title":"Eligibility, joining and national action plans","mustKnow":[{"type":"paragraph","text":[{"text":"4 eligibility areas","bold":true},{"text":" (each scored up to "},{"text":"4 points","bold":true},{"text":", so maximum "},{"text":"16","bold":true},{"text":"):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Fiscal transparency:","bold":true},{"text":" timely publication of the executive's budget proposal (2 points) and the audit report (2 points)."}]},{"text":[{"text":"Access to information:","bold":true},{"text":" "},{"text":"4","bold":true},{"text":" points for an access to information (freedom of information) "},{"text":"law in force","bold":true},{"text":"; 3 for a constitutional guarantee; 1 for a draft law."}]},{"text":[{"text":"Asset disclosure","bold":true},{"text":" by public officials: "},{"text":"4","bold":true},{"text":" points when the law requires disclosure "},{"text":"and the information is public","bold":true},{"text":"; 2 when disclosure is required but not public; 0 with no law."}]},{"text":[{"text":"Citizen engagement:","bold":true},{"text":" based on a civil liberties score."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Threshold:","bold":true},{"text":" at least "},{"text":"75%","bold":true},{"text":" of applicable points ("},{"text":"12 of 16","bold":true},{"text":", or 9 of 12 if one area cannot be measured). GDP, military strength or NATO membership do "},{"text":"not","bold":true},{"text":" count."}]},{"text":[{"text":"Values Check:","bold":true},{"text":" a further test of whether "},{"text":"civil society can operate freely","bold":true},{"text":" (civic space)."}]},{"text":[{"text":"To join:","bold":true},{"text":" endorse the "},{"text":"Open Government Declaration","bold":true},{"text":" and submit a "},{"text":"letter of intent","bold":true},{"text":" from a minister confirming agreement with the Declaration and intent to participate, naming a "},{"text":"lead agency","bold":true},{"text":" and a "},{"text":"point of contact","bold":true},{"text":"."}]},{"text":[{"text":"National action plan (NAP):","bold":true},{"text":" the document setting out the specific commitments a member will implement over a fixed period. Commitments are "},{"text":"co-created","bold":true},{"text":" by government and civil society."}]},{"text":[{"text":"Commitment:","bold":true},{"text":" a specific, time-bound reform in a NAP, e.g. publishing all public contracts online."}]},{"text":[{"text":"Co-creation:","bold":true},{"text":" government and civil society designing the commitments together."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example:","bold":true},{"text":" a country scores fiscal transparency 2 (budget published, audit not), access to information 4 (FOI law in force), asset disclosure 2 (required but not public), citizen engagement 3."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total = 2 + 4 + 2 + 3 = "},{"text":"11 points","bold":true},{"text":". Share = 11 ÷ 16 × 100 = "},{"text":"68.75%","bold":true},{"text":", below 75%, so "},{"text":"not eligible","bo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 30, $study_guide$ld":true},{"text":"."}]},{"text":[{"text":"If it begins publishing its audit report on time, fiscal transparency becomes 4 and the total becomes 13. Share = 13 ÷ 16 × 100 = "},{"text":"81.25%","bold":true},{"text":": "},{"text":"eligible","bold":true},{"text":", subject to the Values Check."}]},{"text":[{"text":"Required minimum: 0.75 × 16 = "},{"text":"12","bold":true},{"text":" points."}]}]}]},{"text":[{"text":"Commitments are put into practice through NAPs, not UN treaties, OGP loans or an OGP parliament. The IRM then assesses them."}]}]}]},{"number":"7.5","title":"Benefits, challenges and Nigeria in OGP","mustKnow":[{"type":"paragraph","text":[{"text":"Benefits:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Greater citizen "},{"text":"access to government information and services","bold":true},{"text":", and greater ability to "},{"text":"hold leaders accountable","bold":true},{"text":"."}]},{"text":[{"text":"Stronger public accountability through "},{"text":"independent assessment","bold":true},{"text":" (IRM)."}]},{"text":[{"text":"Peer learning","bold":true},{"text":" from other governments."}]},{"text":[{"text":"Better policies from diverse inputs; higher "},{"text":"public trust","bold":true},{"text":"."}]},{"text":[{"text":"Reduced corruption through open contracting, asset disclosure and beneficial ownership transparency."}]},{"text":[{"text":"Use of technology for better service delivery."}]}]},{"type":"paragraph","text":[{"text":"OGP does "},{"text":"not","bold":true},{"text":" cancel foreign debts or transfer public assets to investors."}]},{"type":"paragraph","text":[{"text":"Challenges:","bold":true},{"text":" weak political will and changes of government; slow or partial implementation of commitments; limited funding and capacity; shrinking civic space; low public awareness and digital access; resistance from officials used to secrecy; commitments that are vague or not ambitious."}]},{"type":"paragraph","text":[{"text":"Nigeria:","bold":true}]},{"type":"table","header":[[{"text":"Fact"}],[{"text":"Detail"}]],"rows":[[[{"text":"Joined OGP"}],[{"text":"2016","bold":true}]],[[{"text":"Event before joining"}],[{"text":"President Buhari reiterated commitments at the "},{"text":"London Anti-Corruption Summit","bold":true},{"text":", May 2016"}]],[[{"text":"First NAP"}],[{"text":"2017-2019","bold":true}]],[[{"text":"Later NAPs"}],[{"text":"2019-2022; 2023-2025; the fourth, a four-year plan, 2026-2029"}]],[[{"text":"First Nigerian state in local programme"}],[{"text":"Kaduna State","bold":true},{"text":", "},{"text":"2018","bold":true}]],[[{"text":"Supporting law"}],[{"text":"Freedom of Information Act 2011","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Nigeria's NAP commitments focus mainly on "},{"text":"fiscal transparency, extractive industries transparency, anti-corruption and access to public information","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"2016 commitments linked to OGP:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A public central register of "},{"text":"beneficial ownership","bold":true},{"text":": shows the "},{"text":"real people who ultimately own or control companies","bold":true},{"text":"."}]},{"text":[{"text":"Full implementation of the "},{"text":"Open Contracting Data Standard","bold":true},{"text":": publishing information and data about public contracts across the "},{"text":"whole procurement process","bold":true},{"text":"."}]},{"text":[{"text":"Disclosure by companies of payments to government for oil, gas and minerals, complementing the "},{"text":"Extractive Industries Transparency Initiative (EITI)","bold":true},{"text":"; Nigeria's arm is NEITI."}]}]}]},{"text":[{"text":"The "},{"text":"FOI Act 2011","bold":true},{"text":", signed in May 2011 under President Goodluck Jonathan, gives Nigeria the maximum 4 points for access to information."}]},{"text":[{"text":"A Nigerian CSO coalition that helps draft NAP commitments and later monitors delivery shows that "},{"text":"government and civil society work as partners","bold":true},{"text":" in designing and monitoring reforms."}]},{"text":[{"text":"The action plan cycle in order:","bold":true},{"text":" (1) government and civil society "},{"text":"co-create","bold":true},{"text":" the plan; (2) the government "},{"text":"implements","bold":true},{"text":" the commitments over the plan period; (3) the "},{"text":"IRM","bold":true},{"text":" assesses design and results; (4) lessons feed into the "},{"text":"next","bold":true},{"text":" plan. This is why OGP treats learning from failure as a route to better future reforms."}]},{"text":[{"text":"How the challenges show up:","bold":true},{"text":" a commitment can be written but never funded; a new administration may lose interest in its predecessor's plan; citizens without internet access or awareness cannot use published data; and officials used to secrecy may delay releasing records even where an FOI law exists. Benefits come only when commitments are specific, funded and monitored."}]},{"text":[{"text":"Trap: OGP is "},{"text":"voluntary","bold":true},{"text":". It has no power to punish a government; its pressure comes from public commitments, peer comparison and independent IRM reports."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"OGP: voluntary partnership of governments and civil society for concrete open-government commitments."}]},{"text":[{"text":"Launched 20 September 2011 at the UN General Assembly, New York, by 8 founders; South Africa the only African founder."}]},{"text":[{"text":"Four values: transparency, civic participation, public accountability, technology and innovation."}]},{"text":[{"text":"Members endorse the Open Government Declaration (4 commitments)."}]},{"text":[{"text":"Steering Committee (equal government and CSOs), rotating co-chair$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 31, $study_guide$s, Support Unit, IRM overseen by the International Experts Panel."}]},{"text":[{"text":"Eligibility: 4 areas × 4 points = 16; need 75% (12 points), plus the Values Check."}]},{"text":[{"text":"Commitments sit in co-created national action plans."}]},{"text":[{"text":"Nigeria: joined 2016 after the London Anti-Corruption Summit; first NAP 2017-2019; Kaduna joined the local programme in 2018."}]}]}],"theory":{"itemId":"cd0e7306-9807-53e5-8847-b8806d659ca9","question":[{"type":"paragraph","text":[{"text":"A country cannot be measured on fiscal transparency, so it is scored on the other three areas only. It earns 4, 2 and 3 points. Is it eligible on the core criteria?"}]}]},"practice":[{"topic":"Open Government Partnerships","named":false}]}},{"kind":"note","itemId":"8220253a-2f29-5860-941b-b5db5adb3a23","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Public Sector Reforms","body":"What public sector reforms are and why governments undertake them; their types, drivers and objectives; the steps to initiate a reform; the features of a successful reform and the reform models (NPM, NPG, PDIA); supporting conditions and obstacles; tools to measure effectiveness; and Nigeria's main reforms.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"What public sector reforms are and why governments undertake them; their types, drivers and objectives; the steps to initiate a reform; the features of a successful reform and the reform models (NPM, NPG, PDIA); supporting conditions and obstacles; tools to measure effectiveness; and Nigeria's main reforms."}],"lessons":[{"number":"8.1","title":"Meaning, reasons, types and objectives","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public sector reforms:","bold":true},{"text":" "},{"text":"deliberate, multifaceted initiatives","bold":true},{"text":" designed to improve the "},{"text":"efficiency, effectiveness, transparency and accountability","bold":true},{"text":" of government machinery, to boost "},{"text":"service delivery and institutional performance","bold":true},{"text":". They often involve restructuring agencies, digitalisation (e-governance), anti-corruption measures and privatisation."}]},{"text":[{"text":"Primary objective:","bold":true},{"text":" to improve the efficiency, effectiveness, accountability and responsiveness of government institutions and services. Not to abolish social programmes, replace elected officials or privatise everything."}]},{"text":[{"text":"Success depends heavily on "},{"text":"implementation and political will","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Reasons for reform:","bold":true},{"text":" poor service delivery; corruption and leakages; ghost workers and a bloated wage bill; high cost of governance; rigid, slow bureaucracy; weak institutions; citizens' demands for accountability; new technology; fiscal pressure."}]},{"type":"paragraph","text":[{"text":"Major types of reform initiative:","bold":true},{"text":" administrative/civil service restructuring; digital transformation (e-governance); strengthening financial management (e.g. IFMIS); anti-corruption measures; public-private partnerships. Abolishing the civil service is "},{"text":"not","bold":true},{"text":" one."}]},{"type":"paragraph","text":[{"text":"3 performance drivers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Transparency and accountability:","bold":true},{"text":" \"due process\" in procurement and anti-graft agencies curb corruption."}]},{"text":[{"text":"Digitalisation:","bold":true},{"text":" systems such as IPPIS improve efficiency."}]},{"text":[{"text":"Capacity building:","bold":true},{"text":" re-professionalisation and training of public employees."}]}]},{"type":"paragraph","text":[{"text":"4 key objectives:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Enhancing service delivery:","bold":true},{"text":" from bureaucratic to citizen-centred, efficient services."}]},{"text":[{"text":"Combating corruption:","bold":true},{"text":" more transparency, fewer chances for graft through technology and oversight."}]},{"text":[{"text":"Economic modernisation:","bold":true},{"text":" aligning public services with "},{"text":"market demands","bold":true},{"text":" and "},{"text":"reducing the cost of governance","bold":true},{"text":"."}]},{"text":[{"text":"Strengthening institutions:","bold":true},{"text":" robust, accountable, professional institutions."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A reform to stop officials inflating contract prices and diverting funds: "},{"text":"combating corruption","bold":true},{"text":". Cutting passport waiting time from six weeks to one week: "},{"text":"enhancing service delivery","bold":true},{"text":". That is a reduction of 5 ÷ 6 × 100 = "},{"text":"83.3%","bold":true},{"text":" (rounded to one decimal place)."}]},{"text":[{"text":"Why each reason drives reform:","bold":true},{"text":" ghost workers inflate the wage bill, so payroll reform (IPPIS) follows; revenue kept in many commercial bank accounts invites leakages, so the TSA follows; inflated contracts drain budgets, so due process in procurement follows; slow, paper-based offices frustrate citizens, so digital services and one-stop shops follow. Every reform should begin from a clear problem like these."}]},{"text":[{"text":"Types versus drivers versus objectives:","bold":true},{"text":" types are "},{"text":"what","italic":true},{"text":" is changed (restructuring, e-governance, financial management, anti-corruption, PPPs); drivers are "},{"text":"how","italic":true},{"text":" performance improves (transparency and accountability, digitalisation, capacity building); objectives are "},{"text":"what for","italic":true},{"text":" (service delivery, anti-corruption, modernisation, institutions). Exams swap these lists, so learn which is which."}]},{"text":[{"text":"Reforms aim $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 32, $study_guide$to create a modern, professional, performance-oriented public sector; impact on financial performance is often positive, while service delivery gains are sometimes limited by poor coordination and lack of a coherent strategy."}]},{"text":[{"text":"Regulatory reform","bold":true},{"text":" simplifies rules to reduce "},{"text":"administrative burden and compliance costs","bold":true},{"text":". Climate-related reform supports "},{"text":"sustainability and resilience","bold":true},{"text":". Asset management reform improves "},{"text":"tracking and utilisation of public assets","bold":true},{"text":"."}]}]}]},{"number":"8.2","title":"Steps to initiate a public sector reform","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Diagnosis and problem identification","bold":true},{"text":" (the "},{"text":"first","bold":true},{"text":" step), including stakeholder consultation."}]},{"text":[{"text":"Collect "},{"text":"baseline data","bold":true},{"text":" on current performance."}]},{"text":[{"text":"Secure a senior political "},{"text":"reform champion","bold":true},{"text":" (political will and leadership)."}]},{"text":[{"text":"Set clear goals, a "},{"text":"strategy","bold":true},{"text":" and "},{"text":"realistic timelines","bold":true},{"text":"."}]},{"text":[{"text":"Set up a "},{"text":"central reform secretariat","bold":true},{"text":" for day-to-day coordination and reporting."}]},{"text":[{"text":"Communicate","bold":true},{"text":" reasons for change and "},{"text":"engage staff, unions and citizens early","bold":true},{"text":"."}]},{"text":[{"text":"Pilot","bold":true},{"text":" in a few agencies, learn, fix, then scale up."}]},{"text":[{"text":"Implement with training and resources."}]},{"text":[{"text":"Monitor and evaluate","bold":true},{"text":" against the baseline and targets; adjust."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Baseline data","bold":true},{"text":" lets later results be compared with the starting position to show whether the reform worked."}]},{"text":[{"text":"Piloting","bold":true},{"text":" tests the reform and fixes problems before scaling up, as Nigeria did when IPPIS began with "},{"text":"seven","bold":true},{"text":" MDAs."}]},{"text":[{"text":"A state merging two agencies faces staff fear of job losses: the remedy is to "},{"text":"communicate the reasons clearly and engage staff and unions early","bold":true},{"text":", not to announce it after the fact."}]},{"text":[{"text":"A "},{"text":"champion","bold":true},{"text":" supplies the "},{"text":"political will","bold":true},{"text":" needed to drive the reform and overcome resistance."}]},{"text":[{"text":"Unrealistic, undefined or arbitrary timelines reduce effectiveness; "},{"text":"realistic","bold":true},{"text":" ones raise it. Hiring foreign consultants first, or restructuring all ministries at once, is not the first step."}]}]}]},{"number":"8.3","title":"Features of a successful reform and reform models","mustKnow":[{"type":"paragraph","text":[{"text":"Successful reforms show a shift towards "},{"text":"citizen-centric service delivery","bold":true},{"text":", more transparency and efficiency. "},{"text":"7 features:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Citizen-centric focus and improved service delivery:","bold":true},{"text":" user-friendly services, e.g. "},{"text":"one-stop shops","bold":true},{"text":" such as "},{"text":"Kenya's Huduma Centres","bold":true},{"text":"."}]},{"text":[{"text":"Transparency and accountability:","bold":true},{"text":" public reporting, due process, less corruption."}]},{"text":[{"text":"New Public Management (NPM) techniques:","bold":true},{"text":" private-sector practices: results-based management, "},{"text":"performance contracting","bold":true},{"text":", contracting out for competition."}]},{"text":[{"text":"Digital transformation:","bold":true},{"text":" analogue to digital (e-government)."}]},{"text":[{"text":"Organisational restructuring and right-sizing:","bold":true},{"text":" eliminating "},{"text":"ghost workers","bold":true},{"text":", rationalising agencies, streamlining processes."}]},{"text":[{"text":"Professionalisation and performance management:","bold":true},{"text":" retraining, "},{"text":"merit","bold":true},{"text":" hiring, open performance appraisals."}]},{"text":[{"text":"Problem-Driven Iterative Adaptation (PDIA):","bold":true},{"text":" solving specific "},{"text":"local","bold":true},{"text":" problems step by step through "},{"text":"experimentation","bold":true},{"text":", rather than copying \"best practice\" blueprints."}]}]},{"type":"paragraph","text":[{"text":"Also named: "},{"text":"decentralisation","bold":true},{"text":"; strong political will, clear leadership, broad stakeholder buy-in and sustained commitment. Retaining rigid, rule-bound procedures is "},{"text":"not","bold":true},{"text":" a feature."}]},{"type":"table","header":[[{"text":"Model"}],[{"text":"Core idea"}]],"rows":[[[{"text":"Traditional (Weberian) bureaucracy"}],[{"text":"Rules, hierarchy, central control"}]],[[{"text":"New Public Management (NPM)","bold":true}],[{"text":"Apply "},{"text":"private-sector management techniques","bold":true},{"text":" for efficiency"}]],[[{"text":"New Public Governance (NPG)","bold":true}],[{"text":"Collaborative networks","bold":true},{"text":" of public, private and civil society actors in service delivery"}]],[[{"text":"PDIA","bold":true}],[{"text":"Local problem-solving by iteration and experimentation"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ghost worker:","bold":true},{"text":" a name on the payroll that does not match a real, working employee."}]},{"text":[{"text":"Performance contracting:","bold":true},{"text":" directors sign agreements with measurable annual targets; continued appointment depends on meeting them."}]},{"text":[{"text":"One centre where citizen$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 33, $study_guide$s register businesses, renew licences and get birth certificates illustrates "},{"text":"citizen-centric one-stop shops","bold":true},{"text":"."}]},{"text":[{"text":"A state ministry tests three small changes in a few schools to cut teacher absenteeism, keeps what works and adjusts the rest: "},{"text":"PDIA","bold":true},{"text":"."}]},{"text":[{"text":"Successful reforms emphasise "},{"text":"performance","bold":true},{"text":" management, aligning staff performance with reform goals."}]}]}]},{"number":"8.4","title":"Requirements, supporting conditions and obstacles","mustKnow":[{"type":"paragraph","text":[{"text":"5 core components (requirements) of reform:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Digital transformation and efficiency:","bold":true},{"text":" IPPIS and GIFMIS to reduce fraud and raise transparency."}]},{"text":[{"text":"Financial management and accountability:","bold":true},{"text":" the "},{"text":"Treasury Single Account (TSA)","bold":true},{"text":" to centralise revenue and reduce leakages."}]},{"text":[{"text":"Structural and institutional reforms:","bold":true},{"text":" restructuring agencies, privatising public enterprises, establishing anti-corruption bodies ("},{"text":"EFCC, ICPC","bold":true},{"text":")."}]},{"text":[{"text":"Administrative and human resource reforms:","bold":true},{"text":" strengthening capacity, enforcing ethics, performance management systems."}]},{"text":[{"text":"Policy and regulatory improvements:","bold":true},{"text":" stronger regulators, "},{"text":"due process","bold":true},{"text":" in procurement, more transparency."}]}]},{"type":"paragraph","text":[{"text":"Supporting conditions:","bold":true},{"text":" sustained "},{"text":"political will","bold":true},{"text":" and commitment; a "},{"text":"politically neutral, capable civil service","bold":true},{"text":" with reform capacity; "},{"text":"adequate funding and human capacity","bold":true},{"text":"; clear strategy and "},{"text":"stakeholder buy-in","bold":true},{"text":"; stable leadership; legal backing; technology infrastructure; peer learning."}]},{"type":"paragraph","text":[{"text":"Obstacles:","bold":true},{"text":" political instability; lack of clear strategies; "},{"text":"resistance to change","bold":true},{"text":"; "},{"text":"implementation gaps","bold":true},{"text":" from lack of political will and poor planning; resource constraints; need for continuous training."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Frequent changes of reform leadership and strategy are "},{"text":"not","bold":true},{"text":" a supporting condition; strong political will is "},{"text":"not","bold":true},{"text":" an obstacle."}]},{"text":[{"text":"Suppressing unions or monopolising the agenda in the presidency undermines buy-in."}]}]}]},{"number":"8.5","title":"Measuring effectiveness and Nigerian reforms","mustKnow":[{"type":"paragraph","text":[{"text":"Measuring effectiveness in Nigeria means assessing improvements in "},{"text":"transparency, financial accountability and service delivery","bold":true},{"text":". "},{"text":"4 categories of indicator:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Financial performance and accountability:","bold":true},{"text":" revenue collected, payroll fraud cut via IPPIS, budgetary control via GIFMIS."}]},{"text":[{"text":"Service delivery and efficiency:","bold":true},{"text":" speed, quality and accessibility of services; impact of due process in procurement."}]},{"text":[{"text":"Institutional strengthening:","bold":true},{"text":" effectiveness of EFCC and ICPC; implementation of "},{"text":"IPSAS","bold":true},{"text":" (International Public Sector Accounting Standards)."}]},{"text":[{"text":"Economic impact:","bold":true},{"text":" contribution to growth, stability and development."}]}]},{"type":"paragraph","text":[{"text":"Tools:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"KPIs","bold":true},{"text":", independently verified, with "},{"text":"service delivery benchmarks","bold":true},{"text":" for objective assessment."}]},{"text":[{"text":"Citizen report cards","bold":true},{"text":" (citizen satisfaction surveys): citizens rate availability, quality and responsiveness."}]},{"text":[{"text":"Benchmarking:","bold":true},{"text":" comparing indicators with similar agencies or good-practice standards."}]},{"text":[{"text":"Performance (value-for-money) audit:","bold":true},{"text":" often by the Auditor-General; checks economy, efficiency and effectiveness."}]},{"text":[{"text":"Public Expenditure Tracking Survey (PETS):","bold":true},{"text":" follows funds from the centre to schools and clinics to see how much arrives."}]},{"text":[{"text":"Management information systems","bold":true},{"text":" such as dashboards; "},{"text":"outcome reporting","bold":true},{"text":" of achieved results against targets."}]}]},{"type":"paragraph","text":[{"text":"Nigerian reforms:","bold":true}]},{"type":"table","header":[[{"text":"Reform"}],[{"text":"Key facts"}]],"rows":[[[{"text":"IPPIS","bold":true},{"text":" (Integrated Payroll and Personnel Information System)"}],[{"text":"Accurate personnel and payroll records; eliminates "},{"text":"ghost workers","bold":true},{"text":". Live "},{"text":"April 2007","bold":true},{"text":" with "},{"text":"7","bold":true},{"text":" pilot MDAs; managed by the "},{"text":"Office of the Accountant-General of the Federation","bold":true},{"text":" since "},{"text":"October 2008","bold":true}]],[[{"text":"GIFMIS","bold":true},{"text":" (Government Integrated Financial Management Information System)"}],[{"text":"Budgetary control","bold":true},{"text":" and financial management"}]],[[{"text":"TSA","bold":true},{"text":" (Treasury Single Account)"}],[{"text":"Consolidates federal revenues into one account at the "},{"text":"Central Bank of Nigeria","bold":true},{"text":"; piloted 2$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 34, $study_guide$012; full adoption by all federal MDAs mandated in "},{"text":"2015","bold":true},{"text":" under "},{"text":"President Buhari","bold":true},{"text":"; credited with boosting revenue (IGR)"}]],[[{"text":"BPSR","bold":true},{"text":" (Bureau of Public Service Reforms)"}],[{"text":"Set up in "},{"text":"2004","bold":true},{"text":"; to "},{"text":"initiate, coordinate, monitor and ensure full implementation","bold":true},{"text":" of reform policies"}]],[[{"text":"Public Procurement Act 2007","bold":true}],[{"text":"Created the "},{"text":"Bureau of Public Procurement","bold":true},{"text":"; put "},{"text":"due process","bold":true},{"text":" on a statutory footing"}]],[[{"text":"BVN","bold":true},{"text":" (Bank Verification Number)"}],[{"text":"Biometric identity for bank customers, introduced by the CBN in 2014"}]],[[{"text":"Freedom of Information Act 2011","bold":true}],[{"text":"Public right of access to government records"}]],[[{"text":"EFCC, ICPC","bold":true}],[{"text":"Anti-corruption bodies (structural and institutional reform)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pairing trap: IPPIS = "},{"text":"payroll fraud","bold":true},{"text":"; GIFMIS = "},{"text":"budgetary control","bold":true},{"text":". IPPIS is sometimes written \"Integrated Personnel and Payroll Information System\"; both name the same system."}]},{"text":[{"text":"Worked example (₦):","bold":true},{"text":" a ministry's monthly wage bill is ₦7,200,000,000 for 48,000 names. After IPPIS enrolment, 1,200 fictitious names are removed."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Average monthly pay = ₦7,200,000,000 ÷ 48,000 = "},{"text":"₦150,000","bold":true},{"text":"."}]},{"text":[{"text":"Monthly saving = 1,200 × ₦150,000 = "},{"text":"₦180,000,000","bold":true},{"text":"; annual saving = ₦180,000,000 × 12 = "},{"text":"₦2,160,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Payroll cut = 1,200 ÷ 48,000 × 100 = "},{"text":"2.5%","bold":true},{"text":"."}]},{"text":[{"text":"Comparing before and after payroll figures measures "},{"text":"financial performance and accountability","bold":true},{"text":"."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reforms: deliberate initiatives to raise efficiency, effectiveness, transparency and accountability; success hinges on implementation and political will."}]},{"text":[{"text":"Drivers: transparency and accountability, digitalisation, capacity building."}]},{"text":[{"text":"Objectives: service delivery, combating corruption, economic modernisation, strengthening institutions."}]},{"text":[{"text":"First step: diagnosis; then baseline, champion, secretariat, communication, pilot, monitoring."}]},{"text":[{"text":"Features: citizen-centric, transparency, NPM, digital, right-sizing, professionalisation, PDIA."}]},{"text":[{"text":"NPM = private-sector techniques; NPG = networks; PDIA = local experimentation."}]},{"text":[{"text":"Measures: financial, service delivery, institutional, economic; tools include KPIs, citizen report cards, benchmarking, VFM audit, PETS."}]},{"text":[{"text":"Nigeria: IPPIS (2007, OAGF), GIFMIS, TSA (CBN, 2015), BPSR (2004), PPA 2007, BVN, FOI Act 2011."}]}]}],"theory":{"itemId":"105cfc66-1c5b-5b64-87d7-dcbda068b99e","question":[{"type":"paragraph","text":[{"text":"Before a reform, a state paid ₦900,000,000 a month to 6,000 names. After IPPIS, 300 ghost workers were removed. Find the yearly saving and say which indicator category it reflects."}]}]},"practice":[{"topic":"Public Sector Reforms","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"feb19c9b-c485-51b7-b062-d972d8bfb77e","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"A Nigerian bank manager has excellent relations with her team, the task is highly structured, and she holds strong formal power to hire, reward and discipline. Using Fiedler's model, which type of leader suits this situation best, and why?"},"answer":{"kind":"model_answer","itemId":"42ca22d0-093a-5f81-9f76-234af9c51336","sourceKey":"guide-answer:1","payload":{"body":"All three of Fiedler's factors are good (leader-member relations good, task structure high, position power strong), so the situation is very favourable. Fiedler found that task-oriented (low-LPC) leaders perform best in very favourable and very unfavourable situations, while relationship-oriented leaders do best only in moderately favourable ones. Because Fiedler treats style as fixed, the bank should place a task-oriented leader here, or change the situation to fit the leader it has."}}},{"kind":"theory_question","itemId":"098f5914-29b6-5321-b310-022818cc5c0e","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"Distinguish transformational from transactional leadership and list the components of each."},"answer":{"kind":"model_answer","itemId":"23d25a26-5b7d-53f6-a5d9-4c95f42479b9","sourceKey":"guide-answer:2","payload":{"body":"Transformational leadership inspires followers to go beyond self-interest by appealing to shared values and vision. Its four dimensions are idealised influence (charisma, the most vital), inspirational motivation, intellectual stimulation and individualised consideration. Transactional leadership rests on exchange: rewards for good performance and sanctions for poor performance. Its three elements are contingent reward, management by exception-active (constant monitoring) and management by exception-passive (stepping in only when problems are serious). Credit Weber (1947) and Bass (1985)."}}},{"kind":"theory_question","itemId":"245ebff8-43a6-5ff8-bdf5-916dbcb39cd6","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"Name Kelley's five follower types and say which type governance needs most, with a reason."},"answer":{"kind":"model_answer","itemId":"192c3295-4eb7-5e1b-8739-f27f0a6ef94e","sourceKey":"guide-answer:3","payload":{"body":"Kelley (1992) classifies followers by independe$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua205', 35, $study_guide$nt thinking and engagement: exemplary (active, independent), conformist (active, unquestioning), passive (dependent on leaders), alienated (critical but disengaged) and pragmatic (flexible, situational). Governance needs exemplary followers most, because they support leaders actively while questioning unethical orders, which strengthens accountability and prevents misuse of power."}}},{"kind":"theory_question","itemId":"cc70d0d1-1eba-599f-9454-cae47c048dda","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Compare the social contract theories of Thomas Hobbes and John Locke."},"answer":{"kind":"model_answer","itemId":"6d27695d-d9c2-524d-b690-39403004ed76","sourceKey":"guide-answer:4","payload":{"body":"Define the social contract (giving up some rights to a central authority to protect others). Hobbes, Leviathan: state of nature a war of all against all, life \"solitary, poor, nasty, brutish and short\"; people surrender rights to an absolute sovereign for peace and security; almost no right to resist. Locke, Two Treatises of Government: state of nature ruled by natural law and reason but insecure; government by consent protects life, liberty and property; if it violates them, people may resist and replace it. Conclude: Hobbes stresses order, Locke stresses limited government and rights."}}},{"kind":"theory_question","itemId":"331009dd-0fe4-56cb-8814-e3b4bee7f661","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Classify each stakeholder using the salience model: (a) a regulator with power and a legitimate but not urgent claim; (b) protesters blocking a road with an urgent but illegitimate claim and power to disrupt; (c) a charity with a legitimate claim only."},"answer":{"kind":"model_answer","itemId":"55554742-5b02-5879-b4c3-cf731a2f65bd","sourceKey":"guide-answer:5","payload":{"body":"(a) Power + legitimacy = dominant. (b) Power + urgency = dangerous. (c) Legitimacy only = discretionary. Add urgency to (a) and it becomes definitive."}}},{"kind":"theory_question","itemId":"9a2aebc6-8335-563c-ae90-7061517369a9","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"A federal agency budgeted ₦50,000,000 to process 20,000 passport applications. It spent ₦48,000,000 and processed 16,000. Compute its cost per application and the share of its target achieved, and say which of the three Es each figure measures."},"answer":{"kind":"model_answer","itemId":"0bf66ea9-6fdf-54cf-b93d-e7a2b6496ecf","sourceKey":"guide-answer:6","payload":{"body":"Cost per application = ₦48,000,000 ÷ 16,000 = ₦3,000; this measures efficiency (input per unit of output). Target achieved = 16,000 ÷ 20,000 × 100 = 80%; this measures effectiveness. Spending ₦48,000,000 against a ₦50,000,000 budget shows economy."}}},{"kind":"theory_question","itemId":"cd0e7306-9807-53e5-8847-b8806d659ca9","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"A country cannot be measured on fiscal transparency, so it is scored on the other three areas only. It earns 4, 2 and 3 points. Is it eligible on the core criteria?"},"answer":{"kind":"model_answer","itemId":"46968364-b751-5698-839f-bbfb999f0d51","sourceKey":"guide-answer:7","payload":{"body":"Applicable maximum = 3 × 4 = 12 points. Score = 4 + 2 + 3 = 9. Share = 9 ÷ 12 × 100 = 75%, which meets the 75% threshold (9 of 12). It is eligible on the core criteria, provided it also passes the Values Check."}}},{"kind":"theory_question","itemId":"105cfc66-1c5b-5b64-87d7-dcbda068b99e","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"Before a reform, a state paid ₦900,000,000 a month to 6,000 names. After IPPIS, 300 ghost workers were removed. Find the yearly saving and say which indicator category it reflects."},"answer":{"kind":"model_answer","itemId":"de1da78f-67d2-5055-8e19-9535295c2fd1","sourceKey":"guide-answer:8","payload":{"body":"Average pay = ₦900,000,000 ÷ 6,000 = ₦150,000. Monthly saving = 300 × ₦150,000 = ₦45,000,000. Yearly saving = ₦45,000,000 × 12 = ₦540,000,000. This is a financial performance and accountability indicator."}}}]}$study_guide$);
